 static float BotCombat_WeaponScore (edict_t *self, int weapon, float dist, qboolean line_of_sight)
 {
 	float score = -10000.f;
 
 	if (!BotCombat_HasWeapon (self, weapon))
 		return score;
 	if (!BotCombat_HasAmmoForWeapon (self, weapon))
 		return score;
 
 	switch (weapon)
