 	case IT_ROCKET_LAUNCHER:
 		score = (dist > 140.f && dist < 900.f) ? (250.f - fabsf (dist - 420.f) * 0.11f) : -150.f;
 		break;
 
 	case IT_LIGHTNING:
 		score = line_of_sight ? (230.f - dist * 0.20f) : -180.f;
 		break;
 
 	default:
 		break;
 	}
 
 	return score;
 }
 
