 void BotCombat_ComputeAim (bot_state_t *bot, edict_t *self, edict_t *enemy, vec3_t out_angles)
 {
 	vec3_t target;
 	vec3_t to_target;
 	vec3_t base_angles;
 	float dist;
 	float bot_skill_value;
 	float lead_time;
 	float jitter;
