 			sv_player->v.flags = (int)sv_player->v.flags & ~FL_GODMODE;
 			SV_ClientPrintf ("godmode OFF\n");
 		}
 		break;
 	default:
 		Con_Printf("god [value] : toggle god mode. values: 0 = off, 1 = on\n");
