 static void Host_Say(qboolean teamonly)
 {
 	int		j;
 	client_t	*client;
 	client_t	*save;
 	const char	*p;
 	char		text[MAXCMDLINE], *p2;
 	qboolean	quoted;
 	qboolean	fromServer = false;
 
 	if (cmd_source == src_command)
 	{
 		if (cls.state != ca_dedicated)
 		{
 			Cmd_ForwardToServer ();
 			return;
 		}
 		fromServer = true;
 		teamonly = false;
 	}
 
 	if (Cmd_Argc () < 2)
 		return;
 
 	save = host_client;
 
 	p = Cmd_Args();
 // remove quotes if present
 	quoted = false;
 	if (*p == '\"')
 	{
 		p++;
 		quoted = true;
 	}
 // turn on color set 1
 	if (!fromServer)
 		q_snprintf (text, sizeof(text), "\001%s: %s", save->name, p);
 	else
 		q_snprintf (text, sizeof(text), "\001<%s> %s", hostname.string, p);
 
 // check length & truncate if necessary
 	j = (int) strlen(text);
 	if (j >= (int) sizeof(text) - 1)
 	{
 		text[sizeof(text) - 2] = '\n';
 		text[sizeof(text) - 1] = '\0';
 	}
 	else
 	{
 		p2 = text + j;
 		while ((const char *)p2 > (const char *)text &&
 			(p2[-1] == '\r' || p2[-1] == '\n' || (p2[-1] == '\"' && quoted)) )
 		{
 			if (p2[-1] == '\"' && quoted)
 				quoted = false;
 			p2[-1] = '\0';
 			p2--;
 		}
 		p2[0] = '\n';
 		p2[1] = '\0';
 	}
 
 	for (j = 0, client = svs.clients; j < svs.maxclients; j++, client++)
 	{
 		if (!client || !client->active || !client->spawned)
 			continue;
 		if (teamplay.value && teamonly && client->edict->v.team != save->edict->v.team)
 			continue;
 		host_client = client;
 		SV_ClientPrintf("%s", text);
 	}
 	host_client = save;
 
 	if (cls.state == ca_dedicated)
 		Sys_Printf("%s", &text[1]);
 }
 
