+struct InstanceData
+{
+	vec4	WorldMatrix[3];
+	vec4	PrevWorldMatrix[3];
+	vec4	NormalMatrix[3];
+	vec4	LightColor; // xyz=LightColor w=Alpha
+	vec4	DLightColor; // xyz=DLightColor
+	vec4	DLightDir;   // xyz=dominant dlight direction
+	vec4	StaticLightDir; // xyz=dominant static light direction
+	float	SkyVisibility;
+	vec3	_PadSky;
