Index: pakfiles/shaders/decal_instanced.vert
===================================================================
--- pakfiles/shaders/decal_instanced.vert	
+++ pakfiles/shaders/decal_instanced.vert	
@@ -0,0 +1,72 @@
+#include "frame_uniforms.glsl"
+
+struct DecalVertex
+{
+	vec3 pos;
+	float u;
+	float v;
+	uint color;
+	uint pad0;
+	uint pad1;
+};
+
+struct DecalInstance
+{
+	uint first_vert;
+	uint num_verts;
+	float fade_alpha;
+	uint light_rgba;
+	vec4 atlas;
+};
+
+layout(std430, binding=1) restrict readonly buffer DecalVertexBlock
+{
+	DecalVertex verts[];
+};
+
+layout(std430, binding=2) restrict readonly buffer DecalInstanceBlock
+{
+	DecalInstance insts[];
+};
+
+layout(location=0) uniform int InstanceBase;
+
+layout(location=0) out vec2 out_uv;
+layout(location=1) out vec4 out_color;
+
+void main()
+{
+	uint inst_index = uint(max(0, InstanceBase) + gl_InstanceID);
+	DecalInstance inst = insts[inst_index];
+	uint tri = uint(gl_VertexID / 3);
+	uint corner = uint(gl_VertexID % 3);
+	uint local_vert = 0u;
+	bool valid = inst.num_verts >= 3u && tri < (inst.num_verts - 2u);
+
+	if (valid)
+	{
+		if (corner == 0u)
+			local_vert = 0u;
+		else if (corner == 1u)
+			local_vert = tri + 1u;
+		else
+			local_vert = tri + 2u;
+	}
+
+	DecalVertex v = verts[inst.first_vert + local_vert];
+	vec2 base_uv = vec2(v.u, v.v);
+	out_uv = inst.atlas.xy + base_uv * (inst.atlas.zw - inst.atlas.xy);
+	out_color = unpackUnorm4x8(v.color);
+	out_color.rgb *= unpackUnorm4x8(inst.light_rgba).rgb;
+	out_color.a *= inst.fade_alpha;
+
+	if (!valid || out_color.a <= 0.0)
+	{
+		gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
+		out_uv = vec2(0.0, 0.0);
+		out_color = vec4(0.0);
+		return;
+	}
+
+	gl_Position = ViewProj * vec4(v.pos, 1.0);
+}

Index: pakfiles/shaders/fogvol_dlight_score.comp
===================================================================
--- pakfiles/shaders/fogvol_dlight_score.comp	
+++ pakfiles/shaders/fogvol_dlight_score.comp	
@@ -0,0 +1,64 @@
+layout(local_size_x=64) in;
+
+struct FogDlightCandidate
+{
+	vec4 pos_rad;       // xyz position, w radius
+	vec4 color_bias;    // rgb color, w score bias
+	uvec4 meta;         // x flags(bit0 inject), y stable id
+};
+
+layout(std430, binding=0) readonly buffer CandidateBuffer
+{
+	FogDlightCandidate candidates[];
+};
+
+layout(std430, binding=1) writeonly buffer SortEntryBuffer
+{
+	uvec4 entries[]; // x score key (desc), y stable id, z candidate index, w reserved
+};
+
+layout(location=0) uniform vec4 ScoreParams0; // xyz vieworg, w candidate_count
+
+uint FloatSortableAsc(float v)
+{
+	uint f = floatBitsToUint(v);
+	return ((f & 0x80000000u) != 0u) ? ~f : (f ^ 0x80000000u);
+}
+
+uint FloatSortableDesc(float v)
+{
+	return ~FloatSortableAsc(v);
+}
+
+void main()
+{
+	uint i = gl_GlobalInvocationID.x;
+	uint count = uint(max(ScoreParams0.w, 0.0));
+	if (i >= entries.length())
+		return;
+
+	if (i >= count)
+	{
+		entries[i] = uvec4(0xffffffffu, 0xffffffffu, i, 0u);
+		return;
+	}
+
+	FogDlightCandidate c = candidates[i];
+	uint flags = c.meta.x;
+	float radius = c.pos_rad.w;
+	float intensity = max(c.color_bias.x, max(c.color_bias.y, c.color_bias.z));
+	float score = 0.0;
+	uint key = 0xffffffffu;
+
+	if ((flags & 1u) != 0u && radius > 0.0 && intensity > 0.0)
+	{
+		vec3 to_light = c.pos_rad.xyz - ScoreParams0.xyz;
+		float dist = length(to_light);
+		score = radius * intensity * c.color_bias.w;
+		score *= 1.0 / (1.0 + 0.0025 * dist);
+		if (score > 0.0)
+			key = FloatSortableDesc(score);
+	}
+
+	entries[i] = uvec4(key, c.meta.y, i, 0u);
+}

Index: pakfiles/shaders/fogvol_static_build.comp
===================================================================
--- pakfiles/shaders/fogvol_static_build.comp	
+++ pakfiles/shaders/fogvol_static_build.comp	
@@ -0,0 +1,72 @@
+layout(local_size_x=64) in;
+
+struct FogLightGpu
+{
+	vec4 pos_rad;
+	vec4 col_int;
+};
+
+layout(std430, binding=0) readonly buffer StaticRgbBuffer
+{
+	float rgb[];
+};
+
+layout(std430, binding=1) readonly buffer StaticWeightBuffer
+{
+	float weight[];
+};
+
+layout(std430, binding=2) writeonly buffer StaticOutLightBuffer
+{
+	FogLightGpu lights[];
+};
+
+layout(location=0) uniform vec4 BuildParams0; // x total_cells, y stride, z out_count, w nx
+layout(location=1) uniform vec4 BuildParams1; // x ny, y nz
+layout(location=2) uniform vec4 BuildMins;
+layout(location=3) uniform vec4 BuildStepRadius; // xyz cell size, w radius
+layout(location=4) uniform vec4 BuildScale; // x color scale
+
+void main()
+{
+	uint i = gl_GlobalInvocationID.x;
+	uint total_cells = uint(max(BuildParams0.x, 0.0));
+	uint stride = uint(max(BuildParams0.y, 1.0));
+	uint out_count = uint(max(BuildParams0.z, 0.0));
+	uint nx = uint(max(BuildParams0.w, 1.0));
+	uint ny = uint(max(BuildParams1.x, 1.0));
+	uint nxy = nx * ny;
+	uint src = i * stride;
+	FogLightGpu out_light;
+
+	if (i >= out_count || src >= total_cells)
+		return;
+
+	out_light.pos_rad = vec4(0.0);
+	out_light.col_int = vec4(0.0);
+
+	if (src < weight.length() && weight[src] > 0.0)
+	{
+		float w = weight[src];
+		uint x = src % nx;
+		uint y = (src / nx) % ny;
+		uint z = (nxy > 0u) ? (src / nxy) : 0u;
+		uint rgb_ofs = src * 3u;
+		vec3 c = vec3(0.0);
+
+		if (rgb_ofs + 2u < rgb.length())
+		{
+			c.x = max(0.0, rgb[rgb_ofs + 0u] / w) * BuildScale.x;
+			c.y = max(0.0, rgb[rgb_ofs + 1u] / w) * BuildScale.x;
+			c.z = max(0.0, rgb[rgb_ofs + 2u] / w) * BuildScale.x;
+		}
+
+		out_light.pos_rad.x = BuildMins.x + (float(x) + 0.5) * BuildStepRadius.x;
+		out_light.pos_rad.y = BuildMins.y + (float(y) + 0.5) * BuildStepRadius.y;
+		out_light.pos_rad.z = BuildMins.z + (float(z) + 0.5) * BuildStepRadius.z;
+		out_light.pos_rad.w = BuildStepRadius.w;
+		out_light.col_int = vec4(c, 1.0);
+	}
+
+	lights[i] = out_light;
+}

Index: pakfiles/shaders/gather_indirect.comp
===================================================================
--- pakfiles/shaders/gather_indirect.comp	
+++ pakfiles/shaders/gather_indirect.comp	
@@ -0,0 +1,48 @@
+layout(local_size_x=64) in;
+
+struct DrawElementsIndirectCommand
+{
+	uint	count;
+	uint	instanceCount;
+	uint	firstIndex;
+	uint	baseVertex;
+	uint	baseInstance;
+};
+
+layout(std430, binding=5) restrict readonly buffer DrawIndirectSrcBuffer
+{
+	DrawElementsIndirectCommand src_cmds[];
+};
+
+layout(std430, binding=6) restrict writeonly buffer DrawIndirectDstBuffer
+{
+	DrawElementsIndirectCommand dst_cmds[];
+};
+
+struct DrawRemap
+{
+	uint src_call;
+	uint instance_data;
+};
+
+layout(std430, binding=7) restrict readonly buffer DrawRemapBuffer
+{
+	DrawRemap remap_data[];
+};
+
+#define MAX_INSTANCES 1024u
+
+void main()
+{
+	uint thread_id = gl_GlobalInvocationID.x;
+	uint num_calls = remap_data.length();
+	if (thread_id >= num_calls)
+		return;
+	DrawRemap remap = remap_data[thread_id];
+	DrawElementsIndirectCommand cmd = src_cmds[remap.src_call];
+	cmd.baseInstance = remap.instance_data / MAX_INSTANCES;
+	cmd.instanceCount = (remap.instance_data % MAX_INSTANCES) + 1u;
+	if (cmd.count == 0u)
+		cmd.instanceCount = 0u;
+	dst_cmds[thread_id] = cmd;
+}

Index: pakfiles/shaders/gpu_bitonic_pairs.comp
===================================================================
--- pakfiles/shaders/gpu_bitonic_pairs.comp	
+++ pakfiles/shaders/gpu_bitonic_pairs.comp	
@@ -0,0 +1,44 @@
+layout(local_size_x=64) in;
+
+layout(std430, binding=0) buffer SortEntryBuffer
+{
+	uvec4 entries[]; // lexicographic sort by x, then y, then z, then w (ascending)
+};
+
+layout(location=0) uniform vec4 SortParams; // x count, y j, z k
+
+int CompareEntries(uvec4 a, uvec4 b)
+{
+	if (a.x < b.x) return -1;
+	if (a.x > b.x) return 1;
+	if (a.y < b.y) return -1;
+	if (a.y > b.y) return 1;
+	if (a.z < b.z) return -1;
+	if (a.z > b.z) return 1;
+	if (a.w < b.w) return -1;
+	if (a.w > b.w) return 1;
+	return 0;
+}
+
+void main()
+{
+	uint i = gl_GlobalInvocationID.x;
+	uint count = uint(max(SortParams.x, 0.0));
+	uint j = uint(max(SortParams.y, 0.0));
+	uint k = uint(max(SortParams.z, 0.0));
+	uint ixj = i ^ j;
+
+	if (i >= count || ixj >= count || ixj <= i)
+		return;
+
+	uvec4 a = entries[i];
+	uvec4 b = entries[ixj];
+	bool up = ((i & k) == 0u);
+	int cmp = CompareEntries(a, b);
+
+	if ((cmp > 0 && up) || (cmp < 0 && !up))
+	{
+		entries[i] = b;
+		entries[ixj] = a;
+	}
+}

