Index: pakfiles/shaders/palette_init.comp
===================================================================
--- pakfiles/shaders/palette_init.comp	
+++ pakfiles/shaders/palette_init.comp	
@@ -0,0 +1,100 @@
+layout(local_size_x=128) in;
+
+layout(location=0) uniform int Offset;
+
+layout(std430, binding=0) restrict readonly buffer PaletteBuffer
+{
+	uint Palette[256];
+};
+
+uvec3 UnpackRGB8(uint c)
+{
+	return uvec3(c, c >> 8, c >> 16) & 255u;
+}
+
+
+layout(r8ui, binding=0) uniform writeonly uimage3D PaletteLUT;
+
+vec3 sRGBToLinearRGB(vec3 v)
+{
+	return mix(v / 12.92, pow((v + 0.055) / 1.055, vec3(2.4)), greaterThan(v, vec3(0.04045)));
+}
+
+// A perceptual color space for image processing - Bjorn Ottosson
+// https://bottosson.github.io/posts/oklab/ 
+vec3 LinearRGBToOKLab(vec3 c)
+{
+	float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
+	float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
+	float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
+
+	float l_ = pow(l, 1./3.);
+	float m_ = pow(m, 1./3.);
+	float s_ = pow(s, 1./3.);
+
+	return vec3(
+		0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_,
+		1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_,
+		0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_
+	);
+}
+
+vec3 NormalizeColor(uvec3 clr8)
+{
+	vec3 clr = vec3(clr8) * (1./255.);
+#if MODE >= 1
+	clr = sRGBToLinearRGB(clr);
+	#if MODE >= 2
+		clr = LinearRGBToOKLab(clr);
+	#endif
+#endif
+	return clr;
+}
+
+float ColorDistanceSquared(vec3 c0, vec3 c1)
+{
+	vec3 delta = c1 - c0;
+#if MODE == 1
+	// Colour metric - Thiadmer Riemersma
+	// https://www.compuphase.com/cmetric.htm 
+	float rmean = (c0.r + c1.r) * 0.5;
+	return dot(delta * delta, vec3(2. + rmean, 4., 3. - rmean));
+#elif MODE == 2
+	delta.x *= 1.25; // lightness
+	delta.z *= 1.5;  // blue-yellow
+#endif
+	return dot(delta, delta);
+}
+
+shared vec3 palcolors[256];
+
+void main()
+{
+	uint groupsize = gl_WorkGroupSize.x * gl_WorkGroupSize.y * gl_WorkGroupSize.z;
+	uint numpasses = (256 + (groupsize - 1u)) / groupsize;
+	uint i, ofs;
+	for (i = 0u, ofs = 0u; i < numpasses; i++, ofs += groupsize)
+	{
+		uint idx = gl_LocalInvocationIndex + ofs;
+		if (idx < 256u)
+			palcolors[idx] = NormalizeColor(UnpackRGB8(Palette[idx]));
+	}
+	memoryBarrierShared();
+	barrier();
+
+	uvec3 gid = gl_GlobalInvocationID + UnpackRGB8(uint(Offset));
+	vec3 target = NormalizeColor((gid << 1) + (gid >> 6));
+	uint bestidx = 0;
+	float bestdist = 1e+32;
+	for (i = 0u; i < 256u; i++)
+	{
+		vec3 candidate = palcolors[i];
+		float dist = ColorDistanceSquared(target, candidate);
+		if (dist < bestdist)
+		{
+			bestidx = i;
+			bestdist = dist;
+		}
+	}
+	imageStore(PaletteLUT, ivec3(gid), uvec4(bestidx, 0, 0, 0));
+}

Index: pakfiles/shaders/palette_postprocess.comp
===================================================================
--- pakfiles/shaders/palette_postprocess.comp	
+++ pakfiles/shaders/palette_postprocess.comp	
@@ -0,0 +1,33 @@
+layout(local_size_x=64) in;
+
+layout(location=0) uniform float Contrast;
+layout(location=1) uniform vec4 BlendColor;
+
+layout(std430, binding=0) restrict readonly buffer PaletteBuffer
+{
+	uint Palette[256];
+};
+
+uvec3 UnpackRGB8(uint c)
+{
+	return uvec3(c, c >> 8, c >> 16) & 255u;
+}
+
+
+layout(std430, binding=1) restrict writeonly buffer DstPaletteBuffer
+{
+	uint DstPalette[256];
+};
+
+void main()
+{
+	float contrast = Contrast;
+	uint idx = gl_GlobalInvocationID.x;
+	if (idx >= 256u)
+		return;
+	vec3 color = vec3(UnpackRGB8(Palette[idx])) * (1./255.);
+	color = mix(color, BlendColor.rgb, BlendColor.a);
+	color *= contrast;
+	uvec3 dst = uvec3(clamp(color, 0., 1.) * 255. + .5);
+	DstPalette[idx] = dst.r | (dst.g << 8) | (dst.b << 16) | 0xff000000u;
+}

Index: pakfiles/shaders/particles.frag
===================================================================
--- pakfiles/shaders/particles.frag	
+++ pakfiles/shaders/particles.frag	
@@ -0,0 +1,127 @@
+#include "frame_uniforms.glsl"
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+vec3 ApplyFog(vec3 clr, vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	fog = clamp(fog, 0.0, 1.0);
+	return mix(Fog.rgb, clr, fog);
+}
+
+// ALU-only 16x16 Bayer matrix
+float bayer01(ivec2 coord)
+{
+	coord &= 15;
+	coord.y ^= coord.x;
+	uint v = uint(coord.y | (coord.x << 8));	// 0  0  0  0 | x3 x2 x1 x0 |  0  0  0  0 | y3 y2 y1 y0
+	v = (v ^ (v << 2)) & 0x3333;				// 0  0 x3 x2 |  0  0 x1 x0 |  0  0 y3 y2 |  0  0 y1 y0
+	v = (v ^ (v << 1)) & 0x5555;				// 0 x3  0 x2 |  0 x1  0 x0 |  0 y3  0 y2 |  0 y1  0 y0
+	v |= v >> 7;								// 0 x3  0 x2 |  0 x1  0 x0 | x3 y3 x2 y2 | x1 y1 x0 y0
+	v = bitfieldReverse(v) >> 24;				// 0  0  0  0 |  0  0  0  0 | y0 x0 y1 x1 | y2 x2 y3 x3
+	return float(v) * (1.0/256.0);
+}
+
+float bayer(ivec2 coord)
+{
+	return bayer01(coord) - 0.5;
+}
+
+// Hash without Sine
+// https://www.shadertoy.com/view/4djSRW 
+float whitenoise01(vec2 p)
+{
+	vec3 p3 = fract(vec3(p.xyx) * .1031);
+	p3 += dot(p3, p3.yzx + 33.33);
+	return fract((p3.x + p3.y) * p3.z);
+}
+
+float whitenoise(vec2 p)
+{
+	return whitenoise01(p) - 0.5;
+}
+
+// Convert uniform distribution to triangle-shaped distribution
+// Input in [0..1], output in [-1..1]
+// Based on https://www.shadertoy.com/view/4t2SDh 
+float tri(float x)
+{
+	float orig = x * 2.0 - 1.0;
+	uint signbit = floatBitsToUint(orig) & 0x80000000u;
+	x = sqrt(abs(orig)) - 1.;
+	x = uintBitsToFloat(floatBitsToUint(x) ^ signbit);
+	return x;
+}
+
+#define DITHER_NOISE(uv) tri(bayer01(ivec2(uv)))
+#define SCREEN_SPACE_NOISE() DITHER_NOISE(floor(gl_FragCoord.xy)+0.5)
+#define SUPPRESS_BANDING() bayer(ivec2(gl_FragCoord.xy))
+
+layout(location=0) in vec2 in_uv;
+layout(location=1) in vec4 in_color;
+layout(location=2) in vec3 in_pos;
+layout(location=3) in vec2 in_stage_uv;
+
+layout(binding=0) uniform sampler2D Tex;
+layout(location=2) uniform vec4 StageColorMul;
+
+#define OUT_COLOR out_fragcolor
+#if OIT
+	vec4 OUT_COLOR;
+	layout(location=0) out vec4 out_accum;
+	layout(location=1) out float out_reveal;
+
+	vec3 GammaToLinear(vec3 v)
+	{
+#if 0
+		return v*v;
+#else
+		return v;
+#endif
+	}
+
+	void main_body();
+
+	void main()
+	{
+		main_body();
+		OUT_COLOR = clamp(OUT_COLOR, 0.0, 1.0);
+		vec4 color = vec4(GammaToLinear(OUT_COLOR.rgb), OUT_COLOR.a);
+		float z = 1./gl_FragCoord.w;
+#if 0
+		float weight = clamp(color.a * color.a * 0.03 / (1e-5 + pow(z/2e5, 2.0)), 1e-2, 3e3);
+#else
+		float weight = clamp(color.a * color.a * 0.03 / (1e-5 + pow(z/1e7, 1.0)), 1e-2, 3e3);
+#endif
+		out_accum = vec4(color.rgb, color.a * weight);
+		out_accum.rgb *= out_accum.a;
+		out_reveal = color.a;
+	}
+
+	#define main main_body
+#else
+	layout(location=0) out vec4 OUT_COLOR;
+        layout(location=1) out vec4 out_velocity;
+#endif // OIT
+
+void main()
+{
+	vec4 texel = texture(Tex, in_stage_uv);
+	out_fragcolor = in_color * texel * StageColorMul;
+#if !OIT
+        out_velocity = vec4(0.0, 0.0, 0.0, 2.0);
+#endif
+	out_fragcolor.rgb = ApplyFog(out_fragcolor.rgb, in_pos);
+	float radius = length(in_uv);
+	float pixel = fwidth(radius);
+	out_fragcolor.a *= clamp((1. - radius) / pixel, 0., 1.);
+#if DITHER
+	if (abs(Fog.w) > 0.)
+	{
+		out_fragcolor.rgb = sqrt(out_fragcolor.rgb);
+		out_fragcolor.rgb += SCREEN_SPACE_NOISE() * ScreenDither;
+		out_fragcolor.rgb *= out_fragcolor.rgb;
+	}
+#else
+	out_fragcolor.rgb += SUPPRESS_BANDING() * ScreenDither;
+#endif
+}

Index: pakfiles/shaders/particles.vert
===================================================================
--- pakfiles/shaders/particles.vert	
+++ pakfiles/shaders/particles.vert	
@@ -0,0 +1,47 @@
+#include "frame_uniforms.glsl"
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+vec3 ApplyFog(vec3 clr, vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	fog = clamp(fog, 0.0, 1.0);
+	return mix(Fog.rgb, clr, fog);
+}
+
+
+layout(location=0) in vec3 in_pos;
+layout(location=1) in vec4 in_color;
+
+layout(location=0) out vec2 out_uv;
+layout(location=1) out vec4 out_color;
+layout(location=2) out vec3 out_pos;
+layout(location=3) out vec2 out_stage_uv;
+
+layout(location=0) uniform vec3 Params;
+#define ProjScale	Params.xy
+#define UVScale	Params.z
+layout(location=1) uniform mat3 StageTexMatrix;
+
+void main()
+{
+	// figure the current corner: (-1, -1), (-1, 1), (1, -1) or (1, 1)
+	uvec2 flipsign = uvec2(gl_VertexID, gl_VertexID >> 1) << 31;
+	vec2 corner = uintBitsToFloat(floatBitsToUint(-1.0) ^ flipsign);
+
+	// project the center of the particle
+	gl_Position = ViewProj * vec4(in_pos, 1.0);
+
+	// hack a scale up to keep particles from disappearing
+	float depthscale = max(1.0 + gl_Position.w * 0.004, 1.08);
+
+	// perform the billboarding
+	gl_Position.xy += ProjScale * uintBitsToFloat(floatBitsToUint(vec2(depthscale)) ^ flipsign);
+
+	out_pos = in_pos - EyePos; // FIXME: use corner position
+	out_uv = corner * UVScale;
+	out_stage_uv = (StageTexMatrix * vec3(corner * 0.5 + 0.5, 1.0)).xy;
+	out_color = in_color;
+#if OIT
+	out_color.a *= 0.9;
+#endif
+}

