+        float centerDepth = 0.0;
+        float depthThresholdRatio = max(MotionParams0.w, 0.0);
+        if (useDepth)
+                centerDepth = SampleLinearDepth(gl_FragCoord.xy, depthInfo);
+
+        /* Simple deterministic 5-tap blur: center + 2 symmetric pairs. */
+        vec3 accum = color.rgb * 0.50;
+        float weight = 0.50;
+        vec2 nearOffsetPx = direction * (radius * 0.5);
+        vec2 farOffsetPx = direction * radius;
+        vec2 nearOffsetUV = nearOffsetPx * invTexSize;
+        vec2 farOffsetUV = farOffsetPx * invTexSize;
+
+        AccumulateMotionSample(accum, weight, uv + nearOffsetUV, gl_FragCoord.xy + nearOffsetPx, viewMin, viewMax, depthInfo, useDepth, centerDepth, depthThresholdRatio, 0.20);
+        AccumulateMotionSample(accum, weight, uv - nearOffsetUV, gl_FragCoord.xy - nearOffsetPx, viewMin, viewMax, depthInfo, useDepth, centerDepth, depthThresholdRatio, 0.20);
+        AccumulateMotionSample(accum, weight, uv + farOffsetUV, gl_FragCoord.xy + farOffsetPx, viewMin, viewMax, depthInfo, useDepth, centerDepth, depthThresholdRatio, 0.05);
+        AccumulateMotionSample(accum, weight, uv - farOffsetUV, gl_FragCoord.xy - farOffsetPx, viewMin, viewMax, depthInfo, useDepth, centerDepth, depthThresholdRatio, 0.05);
+
+        if (weight <= 0.0)
+                return;
+
+        vec3 blurred = accum / weight;
+        float blurBlend = clamp((radius - stableMinVelocity) / max(maxRadius - stableMinVelocity, 1e-3), 0.0, 1.0);
+        color.rgb = mix(color.rgb, blurred, blurBlend * 0.85);
+}

Index: pakfiles/shaders/q3p_cull_key.comp
===================================================================
--- pakfiles/shaders/q3p_cull_key.comp	
+++ pakfiles/shaders/q3p_cull_key.comp	
@@ -0,0 +1,122 @@
+layout(local_size_x=64) in;
+
+struct Q3PParticle
+{
+	vec4 spawn_life_size_sizeramp;   // x spawn_time, y lifetime, z size, w size_ramp
+	vec4 alpha_alpharamp_gravity_drag; // x alpha, y alpha_ramp, z gravity, w drag
+	vec4 org;                        // xyz origin
+	vec4 vel;                        // xyz velocity
+	uvec4 color_flags_material_alive; // x color, y flags, z material_id, w alive
+	vec4 bounce;                     // x restitution, y min_bounce_speed
+};
+
+layout(std430, binding=0) readonly buffer ParticleBuffer
+{
+	Q3PParticle particles[];
+};
+
+layout(std430, binding=1) writeonly buffer SortEntryBuffer
+{
+	uvec4 entries[]; // x key0, y key1, z particle index, w visible flag
+};
+
+layout(std430, binding=2) buffer VisibleCountBuffer
+{
+	uint visible_count;
+};
+
+layout(location=0) uniform vec4 CullParams0; // x active_count, y cull_dist_sq, z sort_enabled, w alpha_pass
+layout(location=1) uniform vec4 CullParams1; // x showtris, y origin_dot_vpn
+layout(location=2) uniform vec4 FrustumPlane0;
+layout(location=3) uniform vec4 FrustumPlane1;
+layout(location=4) uniform vec4 FrustumPlane2;
+layout(location=5) uniform vec4 FrustumPlane3;
+layout(location=6) uniform vec4 ViewOrg;
+layout(location=7) uniform vec4 ViewDir;
+
+uint Q3P_FloatSortableAsc(float v)
+{
+	uint f = floatBitsToUint(v);
+	return ((f & 0x80000000u) != 0u) ? ~f : (f ^ 0x80000000u);
+}
+
+uint Q3P_FloatSortableDesc(float v)
+{
+	return ~Q3P_FloatSortableAsc(v);
+}
+
+bool Q3P_InsideFrustum(vec3 p, float radius)
+{
+	if (dot(FrustumPlane0.xyz, p) - FrustumPlane0.w <= -radius)
+		return false;
+	if (dot(FrustumPlane1.xyz, p) - FrustumPlane1.w <= -radius)
+		return false;
+	if (dot(FrustumPlane2.xyz, p) - FrustumPlane2.w <= -radius)
+		return false;
+	if (dot(FrustumPlane3.xyz, p) - FrustumPlane3.w <= -radius)
+		return false;
+	return true;
+}
+
+void main()
+{
+	uint i = gl_GlobalInvocationID.x;
+	uint active_count = uint(max(CullParams0.x, 0.0));
+	if (i >= entries.length())
+		return;
+
+	if (i >= active_count)
+	{
+		entries[i] = uvec4(0xffffffffu, 0xffffffffu, i, 0u);
+		return;
+	}
+
+	Q3PParticle p = particles[i];
+	bool showtris = (CullParams1.x > 0.5);
+	bool sort_enabled = (CullParams0.z > 0.5);
+	bool alpha_pass = (CullParams0.w > 0.5);
+	bool visible = (p.color_flags_material_alive.w != 0u);
+	uint blend_group = (p.alpha_alpharamp_gravity_drag.x < 1.0) ? 1u : 0u;
+	uint material_id = p.color_flags_material_alive.z;
+	float radius = max(0.5, p.spawn_life_size_sizeramp.z * 0.5);
+	uint key0 = 0xffffffffu;
+	uint key1 = 0xffffffffu;
+
+	if (!showtris && ((blend_group != 0u) != alpha_pass))
+		visible = false;
+
+	if (visible && CullParams0.y > 0.0)
+	{
+		vec3 to_particle = p.org.xyz - ViewOrg.xyz;
+		visible = dot(to_particle, to_particle) <= CullParams0.y;
+	}
+
+	if (visible)
+		visible = Q3P_InsideFrustum(p.org.xyz, radius);
+
+	if (visible)
+	{
+		float depth = dot(p.org.xyz, ViewDir.xyz) - CullParams1.y;
+		uint depth_key = Q3P_FloatSortableDesc(depth);
+
+		if (sort_enabled && alpha_pass)
+		{
+			key0 = depth_key;
+			key1 = material_id;
+		}
+		else if (sort_enabled && !alpha_pass)
+		{
+			key0 = material_id;
+			key1 = depth_key;
+		}
+		else
+		{
+			key0 = material_id;
+			key1 = i;
+		}
+
+		atomicAdd(visible_count, 1u);
+	}
+
+	entries[i] = uvec4(key0, key1, i, visible ? 1u : 0u);
+}

Index: pakfiles/shaders/q3p_sim.comp
===================================================================
--- pakfiles/shaders/q3p_sim.comp	
+++ pakfiles/shaders/q3p_sim.comp	
@@ -0,0 +1,85 @@
+layout(local_size_x=64) in;
+
+struct Q3PParticle
+{
+	vec4 spawn_life_size_sizeramp;   // x spawn_time, y lifetime, z size, w size_ramp
+	vec4 alpha_alpharamp_gravity_drag; // x alpha, y alpha_ramp, z gravity, w drag
+	vec4 org;                        // xyz origin
+	vec4 vel;                        // xyz velocity
+	uvec4 color_flags_material_alive; // x color, y flags, z material_id, w alive
+	vec4 bounce;                     // x restitution, y min_bounce_speed
+};
+
+layout(std430, binding=0) readonly buffer SrcParticles
+{
+	Q3PParticle src_particles[];
+};
+
+layout(std430, binding=1) writeonly buffer DstParticles
+{
+	Q3PParticle dst_particles[];
+};
+
+layout(location=0) uniform vec4 SimParams0; // x time, y dt, z collision enabled, w active count
+layout(location=1) uniform vec4 SimParams1; // x collision plane z
+
+bool Q3P_IsFinite1(float v)
+{
+	return !isnan(v) && !isinf(v);
+}
+
+bool Q3P_IsFinite3(vec3 v)
+{
+	return Q3P_IsFinite1(v.x) && Q3P_IsFinite1(v.y) && Q3P_IsFinite1(v.z);
+}
+
+void main()
+{
+	uint i = gl_GlobalInvocationID.x;
+	uint active_count = uint(max(SimParams0.w, 0.0));
+	if (i >= active_count)
+		return;
+
+	Q3PParticle p = src_particles[i];
+	float sim_time = SimParams0.x;
+	float dt = max(SimParams0.y, 0.0);
+	float age = sim_time - p.spawn_life_size_sizeramp.x;
+	float lifetime = p.spawn_life_size_sizeramp.y;
+	uint flags = p.color_flags_material_alive.y;
+	uint alive = 1u;
+
+	if (lifetime <= 0.0 || age < 0.0 || age >= lifetime)
+		alive = 0u;
+
+	if (!Q3P_IsFinite3(p.org.xyz) || !Q3P_IsFinite3(p.vel.xyz) || !Q3P_IsFinite1(p.alpha_alpharamp_gravity_drag.x) || !Q3P_IsFinite1(p.spawn_life_size_sizeramp.z))
+		alive = 0u;
+
+	if (alive != 0u)
+	{
+		vec3 prev_org = p.org.xyz;
+		vec3 next_org;
+
+		p.spawn_life_size_sizeramp.z += p.spawn_life_size_sizeramp.w * dt;
+		p.alpha_alpharamp_gravity_drag.x = clamp(
+			p.alpha_alpharamp_gravity_drag.x + p.alpha_alpharamp_gravity_drag.y * dt,
+			0.0, 1.0);
+
+		next_org = prev_org + p.vel.xyz * dt;
+		p.vel.z -= p.alpha_alpharamp_gravity_drag.z * dt;
+		p.vel.xyz *= max(0.0, 1.0 - p.alpha_alpharamp_gravity_drag.w * dt);
+
+		// Cheap optional fallback collision plane; exact world collision keeps CPU fallback.
+		if (SimParams0.z > 0.5 && (flags & 1u) != 0u && next_org.z < SimParams1.x)
+		{
+			next_org.z = SimParams1.x;
+			p.vel.z = -p.vel.z * clamp(p.bounce.x, 0.0, 1.0);
+			if (length(p.vel.xyz) < max(0.0, p.bounce.y))
+				alive = 0u;
+		}
+
+		p.org.xyz = next_org;
+	}
+
+	p.color_flags_material_alive.w = alive;
+	dst_particles[i] = p;
+}

Index: pakfiles/shaders/sky_boxside.frag
===================================================================
--- pakfiles/shaders/sky_boxside.frag	
+++ pakfiles/shaders/sky_boxside.frag	
@@ -0,0 +1,74 @@
+layout(binding=0) uniform sampler2D Tex;
+
+// ALU-only 16x16 Bayer matrix
+float bayer01(ivec2 coord)
+{
+	coord &= 15;
+	coord.y ^= coord.x;
+	uint v = uint(coord.y | (coord.x << 8));	// 0  0  0  0 | x3 x2 x1 x0 |  0  0  0  0 | y3 y2 y1 y0
+	v = (v ^ (v << 2)) & 0x3333;				// 0  0 x3 x2 |  0  0 x1 x0 |  0  0 y3 y2 |  0  0 y1 y0
+	v = (v ^ (v << 1)) & 0x5555;				// 0 x3  0 x2 |  0 x1  0 x0 |  0 y3  0 y2 |  0 y1  0 y0
+	v |= v >> 7;								// 0 x3  0 x2 |  0 x1  0 x0 | x3 y3 x2 y2 | x1 y1 x0 y0
+	v = bitfieldReverse(v) >> 24;				// 0  0  0  0 |  0  0  0  0 | y0 x0 y1 x1 | y2 x2 y3 x3
+	return float(v) * (1.0/256.0);
+}
+
+float bayer(ivec2 coord)
+{
+	return bayer01(coord) - 0.5;
+}
+
+// Hash without Sine
+// https://www.shadertoy.com/view/4djSRW 
+float whitenoise01(vec2 p)
+{
+	vec3 p3 = fract(vec3(p.xyx) * .1031);
+	p3 += dot(p3, p3.yzx + 33.33);
+	return fract((p3.x + p3.y) * p3.z);
+}
+
+float whitenoise(vec2 p)
+{
+	return whitenoise01(p) - 0.5;
+}
+
+// Convert uniform distribution to triangle-shaped distribution
+// Input in [0..1], output in [-1..1]
+// Based on https://www.shadertoy.com/view/4t2SDh 
+float tri(float x)
+{
+	float orig = x * 2.0 - 1.0;
+	uint signbit = floatBitsToUint(orig) & 0x80000000u;
+	x = sqrt(abs(orig)) - 1.;
+	x = uintBitsToFloat(floatBitsToUint(x) ^ signbit);
+	return x;
+}
+
+#define DITHER_NOISE(uv) tri(bayer01(ivec2(uv)))
+#define SCREEN_SPACE_NOISE() DITHER_NOISE(floor(gl_FragCoord.xy)+0.5)
+#define SUPPRESS_BANDING() bayer(ivec2(gl_FragCoord.xy))
+
+layout(location=2) uniform vec4 Fog;
+layout(location=3) uniform float ScreenDither;
+
+layout(location=0) in vec3 in_dir;
+layout(location=1) in vec2 in_uv;
+
+layout(location=0) out vec4 out_fragcolor;
+layout(location=1) out vec4 out_velocity;
+
+void main()
+{
+	out_fragcolor = texture(Tex, in_uv);
+        out_velocity = vec4(0.0, 0.0, 0.0, 3.0);
+	// BUG FIX: use abs(Fog.w) — negative CPU fog density must not invert attenuation.
+	// Consistent with world.frag, sky_cubemap.frag and sky_layers.frag conventions.
+	out_fragcolor.rgb = mix(out_fragcolor.rgb, Fog.rgb, abs(Fog.w));
+#if DITHER
+	out_fragcolor.rgb = sqrt(out_fragcolor.rgb);
+	out_fragcolor.rgb += SCREEN_SPACE_NOISE() * ScreenDither;
+	out_fragcolor.rgb *= out_fragcolor.rgb;
+#else
+	out_fragcolor.rgb += SUPPRESS_BANDING() * ScreenDither;
+#endif
+}

Index: pakfiles/shaders/sky_boxside.vert
===================================================================
--- pakfiles/shaders/sky_boxside.vert	
+++ pakfiles/shaders/sky_boxside.vert	
@@ -0,0 +1,23 @@
+layout(location=0) uniform mat4 MVP;
+layout(location=1) uniform vec3 EyePos;
+
+layout(location=0) in vec3 in_dir;
+layout(location=1) in vec2 in_uv;
+
+layout(location=0) out vec3 out_dir;
+layout(location=1) out vec2 out_uv;
+
+void main()
+{
+	gl_Position = MVP * vec4(EyePos + in_dir, 1.0);
+	// BUG FIX: with reversed-Z the far plane lives at z/w = 0.0, not 1.0.
+	// Setting z = w maps to z/w = 1.0 which is the NEAR plane in reversed-Z —
+	// skybox would overdraw everything. Use z = 0 for reversed-Z far plane.
+#if REVERSED_Z
+	gl_Position.z = 0.0;
+#else
+	gl_Position.z = gl_Position.w;
+#endif
+	out_dir = in_dir;
+	out_uv = in_uv;
+}

Index: pakfiles/shaders/sky_cubemap.frag
