--- pakfiles/shaders/sky_cubemap.frag	
+++ pakfiles/shaders/sky_cubemap.frag	
@@ -0,0 +1,103 @@
+#include "frame_uniforms.glsl"
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+vec3 ApplyFog(vec3 clr, vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	fog = clamp(fog, 0.0, 1.0);
+	return mix(Fog.rgb, clr, fog);
+}
+
+// ALU-only 16x16 Bayer matrix
+float bayer01(ivec2 coord)
+{
+	coord &= 15;
+	coord.y ^= coord.x;
+	uint v = uint(coord.y | (coord.x << 8));	// 0  0  0  0 | x3 x2 x1 x0 |  0  0  0  0 | y3 y2 y1 y0
+	v = (v ^ (v << 2)) & 0x3333;				// 0  0 x3 x2 |  0  0 x1 x0 |  0  0 y3 y2 |  0  0 y1 y0
+	v = (v ^ (v << 1)) & 0x5555;				// 0 x3  0 x2 |  0 x1  0 x0 |  0 y3  0 y2 |  0 y1  0 y0
+	v |= v >> 7;								// 0 x3  0 x2 |  0 x1  0 x0 | x3 y3 x2 y2 | x1 y1 x0 y0
+	v = bitfieldReverse(v) >> 24;				// 0  0  0  0 |  0  0  0  0 | y0 x0 y1 x1 | y2 x2 y3 x3
+	return float(v) * (1.0/256.0);
+}
+
+float bayer(ivec2 coord)
+{
+	return bayer01(coord) - 0.5;
+}
+
+// Hash without Sine
+// https://www.shadertoy.com/view/4djSRW 
+float whitenoise01(vec2 p)
+{
+	vec3 p3 = fract(vec3(p.xyx) * .1031);
+	p3 += dot(p3, p3.yzx + 33.33);
+	return fract((p3.x + p3.y) * p3.z);
+}
+
+float whitenoise(vec2 p)
+{
+	return whitenoise01(p) - 0.5;
+}
+
+// Convert uniform distribution to triangle-shaped distribution
+// Input in [0..1], output in [-1..1]
+// Based on https://www.shadertoy.com/view/4t2SDh 
+float tri(float x)
+{
+	float orig = x * 2.0 - 1.0;
+	uint signbit = floatBitsToUint(orig) & 0x80000000u;
+	x = sqrt(abs(orig)) - 1.;
+	x = uintBitsToFloat(floatBitsToUint(x) ^ signbit);
+	return x;
+}
+
+#define DITHER_NOISE(uv) tri(bayer01(ivec2(uv)))
+#define SCREEN_SPACE_NOISE() DITHER_NOISE(floor(gl_FragCoord.xy)+0.5)
+#define SUPPRESS_BANDING() bayer(ivec2(gl_FragCoord.xy))
+
+layout(binding=2) uniform samplerCube Skybox;
+
+layout(location=0) in vec3 in_dir;
+
+layout(location=0) out vec4 out_fragcolor;
+layout(location=1) out vec4 out_velocity;
+
+void main()
+{
+#if ANIM
+	float t1 = WindPhase;
+	float t2 = fract(t1) - 0.5;
+	// BUG FIX: blend must be derived from fract(t1) so it stays in [0,1].
+	// Original abs(t1 * 2.0) grows unbounded → layer alpha goes negative → black sky flicker.
+	float blend = abs(fract(t1) * 2.0 - 1.0);
+	vec3 dir = normalize(in_dir);
+	// BUG FIX: base was sampled with un-normalized in_dir while layers used normalized dir.
+	// Cubemap hardware normalizes internally, but using the same dir keeps
+	// texel footprints consistent and avoids subtle mip-level divergence.
+	vec4 base = texture(Skybox, dir);
+	vec4 layer1 = texture(Skybox, dir + t1 * WindDir);
+	vec4 layer2 = texture(Skybox, dir + t2 * WindDir);
+	layer1.a *= 1.0 - blend;
+	layer2.a *= blend;
+	layer1.rgb *= layer1.a;
+	layer2.rgb *= layer2.a;
+	vec4 combined = layer1 + layer2;
+	// BUG FIX: combined.a can exceed 1.0 when both layers are semi-opaque.
+	// Clamp before using as coverage weight to prevent base.rgb going negative.
+	combined.a = clamp(combined.a, 0.0, 1.0);
+	out_fragcolor = vec4(base.rgb * (1.0 - combined.a) + combined.rgb, 1);
+	out_velocity = vec4(0.0, 0.0, 0.0, 3.0);
+#else
+	out_fragcolor = texture(Skybox, in_dir);
+        out_velocity = vec4(0.0, 0.0, 0.0, 3.0);
+#endif
+	out_fragcolor.rgb = mix(out_fragcolor.rgb, SkyFog.rgb, SkyFog.a);
+#if DITHER
+	out_fragcolor.rgb = sqrt(out_fragcolor.rgb);
+	out_fragcolor.rgb += SCREEN_SPACE_NOISE() * ScreenDither;
+	out_fragcolor.rgb *= out_fragcolor.rgb;
+#else
+	out_fragcolor.rgb += SUPPRESS_BANDING() * ScreenDither;
+#endif
+}

Index: pakfiles/shaders/sky_cubemap.vert
===================================================================
--- pakfiles/shaders/sky_cubemap.vert	
+++ pakfiles/shaders/sky_cubemap.vert	
@@ -0,0 +1,100 @@
+#if BINDLESS
+	#extension GL_ARB_shader_draw_parameters : require
+	#define DRAW_ID			gl_DrawIDARB
+#else
+	layout(location=0) uniform int DrawID;
+	#define DRAW_ID			DrawID
+#endif
+
+#include "frame_uniforms.glsl"
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+vec3 ApplyFog(vec3 clr, vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	fog = clamp(fog, 0.0, 1.0);
+	return mix(Fog.rgb, clr, fog);
+}
+
+struct Call
+{
+	uint	flags;
+	uint	tcgen;
+	float	wateralpha;
+	int		spec_mode;
+	vec2	polygon_offset;
+	vec2	specular; // x=intensity y=exponent
+	vec4	stage_color;
+#if BINDLESS
+	uvec2	txhandle;
+	uvec2	fbhandle;
+	uvec2	emhandle;
+	uvec2	nmhandle;
+	uvec2	smhandle;
+#else
+	int		baseinstance;
+	int		padding[3];
+#endif // BINDLESS
+};
+const uint
+	CF_USE_POLYGON_OFFSET = 1u,
+	CF_USE_FULLBRIGHT = 2u,
+	CF_NOLIGHTMAP = 4u,
+	CF_USE_EMISSIVE = 8u
+;
+
+layout(std430, binding=1) restrict readonly buffer CallBuffer
+{
+	Call call_data[];
+};
+
+#if BINDLESS
+	#define GET_INSTANCE_ID(call) (gl_BaseInstanceARB + gl_InstanceID)
+#else
+	#define GET_INSTANCE_ID(call) (call.baseinstance + gl_InstanceID)
+#endif
+struct Instance
+{
+	vec4	mat[3];
+	vec4	prev_mat[3];
+	float	alpha;
+	float	pad0;
+	float	pad1;
+	float	pad2;
+};
+
+layout(std430, binding=2) restrict readonly buffer InstanceBuffer
+{
+	Instance instance_data[];
+};
+
+vec3 TransformPosition(vec3 p, vec4 mat[3])
+{
+	mat4x3 world = transpose(mat3x4(mat[0], mat[1], mat[2]));
+	return (world * vec4(p, 1.0)).xyz;
+}
+
+vec3 Transform(vec3 p, Instance instance)
+{
+	return TransformPosition(p, instance.mat);
+}
+
+layout(location=0) in vec3 in_pos;
+layout(location=1) in vec4 in_uv;
+layout(location=2) in float in_lmofs;
+layout(location=3) in ivec4 in_styles;
+
+
+layout(location=0) out vec3 out_dir;
+
+void main()
+{
+	Call call = call_data[DRAW_ID];
+	int instance_id = GET_INSTANCE_ID(call);
+	Instance instance = instance_data[instance_id];
+	vec3 pos = Transform(in_pos, instance);
+	gl_Position = ViewProj * vec4(pos, 1.0);
+	out_dir.x = -(pos.y - EyePos.y);
+	out_dir.y =  (pos.z - EyePos.z);
+	out_dir.z =  (pos.x - EyePos.x);
+}

