Index: pakfiles/shaders/water.frag
===================================================================
--- pakfiles/shaders/water.frag	
+++ pakfiles/shaders/water.frag	
@@ -0,0 +1,193 @@
+#if BINDLESS
+        #extension GL_ARB_bindless_texture : require
+#else
+        layout(binding=0) uniform sampler2D Tex;
+        layout(binding=1) uniform sampler2D FullbrightTex;
+        layout(binding=4) uniform sampler2D EmissiveTex;
+#endif
+
+#include "frame_uniforms.glsl"
+
+const uint
+        CF_USE_POLYGON_OFFSET = 1u,
+        CF_USE_FULLBRIGHT = 2u,
+        CF_NOLIGHTMAP = 4u,
+        CF_USE_EMISSIVE = 8u,
+        CF_ALPHA_TEST = 16u,
+        CF_MAT_BLOOM = 128u,
+        CF_MAT_EMISSIVE = 256u,
+        CF_MAT_HAS_SHADER = 4096u
+;
+
+// ALU-only 16x16 Bayer matrix
+float bayer01(ivec2 coord)
+{
+	coord &= 15;
+	coord.y ^= coord.x;
+	uint v = uint(coord.y | (coord.x << 8));	// 0  0  0  0 | x3 x2 x1 x0 |  0  0  0  0 | y3 y2 y1 y0
+	v = (v ^ (v << 2)) & 0x3333;				// 0  0 x3 x2 |  0  0 x1 x0 |  0  0 y3 y2 |  0  0 y1 y0
+	v = (v ^ (v << 1)) & 0x5555;				// 0 x3  0 x2 |  0 x1  0 x0 |  0 y3  0 y2 |  0 y1  0 y0
+	v |= v >> 7;								// 0 x3  0 x2 |  0 x1  0 x0 | x3 y3 x2 y2 | x1 y1 x0 y0
+	v = bitfieldReverse(v) >> 24;				// 0  0  0  0 |  0  0  0  0 | y0 x0 y1 x1 | y2 x2 y3 x3
+	return float(v) * (1.0/256.0);
+}
+
+float bayer(ivec2 coord)
+{
+	return bayer01(coord) - 0.5;
+}
+
+// Hash without Sine
+// https://www.shadertoy.com/view/4djSRW 
+float whitenoise01(vec2 p)
+{
+	vec3 p3 = fract(vec3(p.xyx) * .1031);
+	p3 += dot(p3, p3.yzx + 33.33);
+	return fract((p3.x + p3.y) * p3.z);
+}
+
+float whitenoise(vec2 p)
+{
+	return whitenoise01(p) - 0.5;
+}
+
+// Convert uniform distribution to triangle-shaped distribution
+// Input in [0..1], output in [-1..1]
+// Based on https://www.shadertoy.com/view/4t2SDh 
+float tri(float x)
+{
+	float orig = x * 2.0 - 1.0;
+	uint signbit = floatBitsToUint(orig) & 0x80000000u;
+	x = sqrt(abs(orig)) - 1.;
+	x = uintBitsToFloat(floatBitsToUint(x) ^ signbit);
+	return x;
+}
+
+#define DITHER_NOISE(uv) tri(bayer01(ivec2(uv)))
+#define SCREEN_SPACE_NOISE() DITHER_NOISE(floor(gl_FragCoord.xy)+0.5)
+#define SUPPRESS_BANDING() bayer(ivec2(gl_FragCoord.xy))
+
+vec2 ComputeVelocity(vec4 curr_clip, vec4 prev_clip)
+{
+	const float EPS = 1e-6;
+	float inv_curr_w = abs(curr_clip.w) > EPS ? 1.0 / curr_clip.w : 0.0;
+	float inv_prev_w = abs(prev_clip.w) > EPS ? 1.0 / prev_clip.w : 0.0;
+	vec2 curr_ndc = curr_clip.xy * inv_curr_w;
+	vec2 prev_ndc = prev_clip.xy * inv_prev_w;
+	return (curr_ndc - prev_ndc) * 0.5;
+}
+
+layout(location=0) flat in uint in_flags;
+layout(location=1) flat in float in_alpha;
+layout(location=2) in vec2 in_uv;
+layout(location=3) in vec3 in_pos;
+#if BINDLESS
+        layout(location=4) flat in uvec4 in_samplers0;
+        layout(location=5) flat in uvec2 in_samplers1;
+#endif
+layout(location=6) noperspective in vec4 in_curr_clip;
+layout(location=7) noperspective in vec4 in_prev_clip;
+
+#define OUT_COLOR out_fragcolor
+#if OIT
+	vec4 OUT_COLOR;
+	layout(location=0) out vec4 out_accum;
+	layout(location=1) out float out_reveal;
+
+	vec3 GammaToLinear(vec3 v)
+	{
+#if 0
+		return v*v;
+#else
+		return v;
+#endif
+	}
+
+	void main_body();
+
+	void main()
+	{
+		main_body();
+		OUT_COLOR = clamp(OUT_COLOR, 0.0, 1.0);
+		vec4 color = vec4(GammaToLinear(OUT_COLOR.rgb), OUT_COLOR.a);
+		float z = 1./gl_FragCoord.w;
+#if 0
+		float weight = clamp(color.a * color.a * 0.03 / (1e-5 + pow(z/2e5, 2.0)), 1e-2, 3e3);
+#else
+		float weight = clamp(color.a * color.a * 0.03 / (1e-5 + pow(z/1e7, 1.0)), 1e-2, 3e3);
+#endif
+		out_accum = vec4(color.rgb, color.a * weight);
+		out_accum.rgb *= out_accum.a;
+		out_reveal = color.a;
+	}
+
+	#define main main_body
+#else
+	layout(location=0) out vec4 OUT_COLOR;
+        layout(location=1) out vec4 out_velocity;
+#endif // OIT
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+void main()
+{
+        vec3 fullbright = vec3(0.0);
+        vec3 emissive = vec3(0.0);
+        vec2 uv = in_uv * 2.0 + 0.125 * sin(in_uv.yx * (3.14159265 * 2.0) + Time);
+#if BINDLESS
+        sampler2D Tex = sampler2D(in_samplers0.xy);
+        if ((in_flags & CF_USE_FULLBRIGHT) != 0u)
+        {
+                sampler2D FullbrightTex = sampler2D(in_samplers0.zw);
+                fullbright = texture(FullbrightTex, uv).rgb;
+        }
+        if ((in_flags & CF_USE_EMISSIVE) != 0u)
+        {
+                sampler2D EmissiveSampler = sampler2D(in_samplers1.xy);
+                emissive = texture(EmissiveSampler, uv).rgb;
+        }
+#else
+        if ((in_flags & CF_USE_FULLBRIGHT) != 0u)
+                fullbright = texture(FullbrightTex, uv).rgb;
+        if ((in_flags & CF_USE_EMISSIVE) != 0u)
+                emissive = texture(EmissiveTex, uv).rgb;
+#endif
+        vec4 result = texture(Tex, uv);
+        int debug_mode = int(ColorSpaceParams.x + 0.5);
+        if (debug_mode == 1)
+        {
+                out_fragcolor = vec4(result.rgb, 1.0);
+#if !OIT
+                out_velocity = vec4(0.0);
+#endif
+                return;
+        }
+        result.rgb += fullbright;
+        result.rgb += emissive;
+        result.rgb = clamp(result.rgb, 0.0, 1.0);
+        float fog = exp2(-abs(Fog.w) * dot(in_pos - EyePos, in_pos - EyePos));
+        fog = clamp(fog, 0.0, 1.0);
+
+        result.rgb = mix(Fog.rgb, result.rgb, fog);
+        result.a *= in_alpha * fog;
+        out_fragcolor = result;
+#if !OIT
+        vec2 velocity = ComputeVelocity(in_curr_clip, in_prev_clip);
+        vec2 velocityOut = vec2(0.0);
+        if (result.a >= 0.999)
+                velocityOut = velocity * result.a;
+        float bloomMask = ((in_flags & CF_MAT_BLOOM) != 0u) ? 1.0 : 0.0;
+        float emissiveMask = ((in_flags & CF_MAT_EMISSIVE) != 0u) ? 4.0 : 0.0;
+        float materialMask = 2.0 + bloomMask + emissiveMask;
+        out_velocity = vec4(velocityOut, 0.0, materialMask);
+#endif
+#if DITHER
+	if (abs(Fog.w) > 0.)
+	{
+		out_fragcolor.rgb = sqrt(out_fragcolor.rgb);
+		out_fragcolor.rgb += SCREEN_SPACE_NOISE() * ScreenDither;
+		out_fragcolor.rgb *= out_fragcolor.rgb;
+	}
+#else
+	out_fragcolor.rgb += SUPPRESS_BANDING() * ScreenDither;
+#endif
+}

Index: pakfiles/shaders/water.vert
===================================================================
--- pakfiles/shaders/water.vert	
+++ pakfiles/shaders/water.vert	
@@ -0,0 +1,129 @@
+#if BINDLESS
+	#extension GL_ARB_shader_draw_parameters : require
+	#define DRAW_ID			gl_DrawIDARB
+#else
+	layout(location=0) uniform int DrawID;
+	#define DRAW_ID			DrawID
+#endif
+
+#include "frame_uniforms.glsl"
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+vec3 ApplyFog(vec3 clr, vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	fog = clamp(fog, 0.0, 1.0);
+	return mix(Fog.rgb, clr, fog);
+}
+
+struct Call
+{
+	uint	flags;
+	uint	tcgen;
+	float	wateralpha;
+	int		spec_mode;
+	vec2	polygon_offset;
+	vec2	specular;
+	vec4	stage_color;
+#if BINDLESS
+	uvec2	txhandle;
+	uvec2	fbhandle;
+	uvec2	emhandle;
+	uvec2	nmhandle;
+	uvec2	smhandle;
+#else
+	int		baseinstance;
+	int		padding[3];
+#endif // BINDLESS
+};
+const uint
+	CF_USE_POLYGON_OFFSET = 1u,
+	CF_USE_FULLBRIGHT = 2u,
+	CF_NOLIGHTMAP = 4u,
+	CF_USE_EMISSIVE = 8u,
+	CF_ALPHA_TEST = 16u
+;
+
+layout(std430, binding=1) restrict readonly buffer CallBuffer
+{
+	Call call_data[];
+};
+
+#if BINDLESS
+	#define GET_INSTANCE_ID(call) (gl_BaseInstanceARB + gl_InstanceID)
+#else
+	#define GET_INSTANCE_ID(call) (call.baseinstance + gl_InstanceID)
+#endif
+struct Instance
+{
+	vec4	mat[3];
+	vec4	prev_mat[3];
+	float	alpha;
+	float	pad0;
+	float	pad1;
+	float	pad2;
+};
+
+layout(std430, binding=2) restrict readonly buffer InstanceBuffer
+{
+	Instance instance_data[];
+};
+
+vec3 TransformPosition(vec3 p, vec4 mat[3])
+{
+	mat4x3 world = transpose(mat3x4(mat[0], mat[1], mat[2]));
+	return (world * vec4(p, 1.0)).xyz;
+}
+
+vec3 Transform(vec3 p, Instance instance)
+{
+	return TransformPosition(p, instance.mat);
+}
+
+vec3 TransformPrev(vec3 p, Instance instance)
+{
+	return TransformPosition(p, instance.prev_mat);
+}
+
+layout(location=0) in vec3 in_pos;
+layout(location=1) in vec4 in_uv;
+layout(location=2) in float in_lmofs;
+layout(location=3) in ivec4 in_styles;
+
+
+layout(location=0) flat out uint out_flags;
+layout(location=1) flat out float out_alpha;
+layout(location=2) out vec2 out_uv;
+layout(location=3) out vec3 out_pos;
+#if BINDLESS
+        layout(location=4) flat out uvec4 out_samplers0;
+        layout(location=5) flat out uvec2 out_samplers1;
+#endif
+layout(location=6) noperspective out vec4 out_curr_clip;
+layout(location=7) noperspective out vec4 out_prev_clip;
+
+void main()
+{
+        Call call = call_data[DRAW_ID];
+        int instance_id = GET_INSTANCE_ID(call);
+        Instance instance = instance_data[instance_id];
+        vec3 world_pos = Transform(in_pos, instance);
+        vec3 prev_world_pos = TransformPrev(in_pos, instance);
+        vec4 curr_clip = ViewProj * vec4(world_pos, 1.0);
+        vec4 prev_clip = PrevViewProj * vec4(prev_world_pos, 1.0);
+        gl_Position = curr_clip;
+        out_curr_clip = curr_clip;
+        out_prev_clip = prev_clip;
+        out_flags = call.flags;
+        out_uv = in_uv.xy;
+        out_pos = world_pos;
+        out_alpha = instance.alpha < 0.0 ? call.wateralpha : instance.alpha;
+#if BINDLESS
+        out_samplers0.xy = call.txhandle;
+        if ((call.flags & CF_USE_FULLBRIGHT) != 0u)
+                out_samplers0.zw = call.fbhandle;
+        else
+                out_samplers0.zw = out_samplers0.xy;
+        out_samplers1.xy = call.emhandle;
+#endif
+}

