+layout(binding=2) uniform sampler2D LMTex;
+layout(binding=3) uniform sampler2D LMTexDir;
+layout(binding=7) uniform sampler2DArray SunShadowTex;
+layout(binding=8) uniform samplerCubeArray DLightShadowTex;
+
