+	float	radius;
+	vec3	color;
+	float	minlight;
+};
+
+layout(std430, binding=0) restrict readonly buffer LightBuffer
+{
+	vec2	LightStyles[64];
+	Light	Lights[];
+};
+
+float GetLightStyle(int index)
+{
+	return (index < 64) ? mix(LightStyles[index].x, LightStyles[index].y, LightmapParams.w) : 1.0;
+}
+
+struct Call
+{
+	uint	flags;
+	uint	tcgen;
+	float	wateralpha;
+	int		spec_mode;
+	vec2	polygon_offset;
+	vec2	specular;
+	vec4	stage_color;
+#if BINDLESS
+	uvec2	txhandle;
+	uvec2	fbhandle;
+	uvec2	emhandle;
+	uvec2	nmhandle;
+	uvec2	smhandle;
+#else
+	int		baseinstance;
+	int		padding[3];
+#endif
+};
+
+const uint
+	CF_USE_POLYGON_OFFSET = 1u,
+	CF_USE_FULLBRIGHT     = 2u,
+	CF_NOLIGHTMAP         = 4u,
+	CF_USE_EMISSIVE       = 8u,
+	CF_ALPHA_TEST         = 16u,
+	CF_MAT_BLOOM          = 128u,
+	CF_MAT_EMISSIVE       = 256u,
