+
+vec2 ComputeVelocity(vec4 curr_clip, vec4 prev_clip)
+{
+	const float EPS = 1e-6;
+	float inv_curr_w = (abs(curr_clip.w) > EPS) ? (1.0 / curr_clip.w) : 0.0;
+	float inv_prev_w = (abs(prev_clip.w) > EPS) ? (1.0 / prev_clip.w) : 0.0;
+	vec2 curr_ndc = curr_clip.xy * inv_curr_w;
+	vec2 prev_ndc = prev_clip.xy * inv_prev_w;
+	return (curr_ndc - prev_ndc) * 0.5;
+}
+
+float DepthToCanonical(float depth)
+{
+#if REVERSED_Z
+	return 1.0 - depth;
+#else
+	return depth;
+#endif
+}
+
+int ShadowSlotForLight(int lightIndex)
+{
+	if (abs(ShadowDLightIndices.x - float(lightIndex)) < 0.5) return 0;
+	if (abs(ShadowDLightIndices.y - float(lightIndex)) < 0.5) return 1;
+	if (abs(ShadowDLightIndices.z - float(lightIndex)) < 0.5) return 2;
+	if (abs(ShadowDLightIndices.w - float(lightIndex)) < 0.5) return 3;
+	return -1;
+}
+
+int ShadowCascadeForWorldPos(vec3 worldPos)
+{
+	int cascades = clamp(ShadowSunCascadeCount, 1, 4);
+	float dist = length(worldPos - EyePos);
+	if (cascades <= 1) return 0;
+	if (dist <= ShadowSunSplits.x) return 0;
+	if (dist <= ShadowSunSplits.y || cascades == 2) return 1;
+	if (dist <= ShadowSunSplits.z || cascades == 3) return 2;
+	return cascades - 1;
+}
+
+float SampleSunShadow(vec3 worldPos)
+{
+	if (ShadowEnableDebug.x < 0.5 || ShadowEnableDebug.y < 0.5)
+		return 1.0;
+
+	int cascade = ShadowCascadeForWorldPos(worldPos);
+	vec4 clip = ShadowSunViewProj[cascade] * vec4(worldPos, 1.0);
+	if (abs(clip.w) <= 1e-6)
+		return 1.0;
+
+	vec3 ndc = clip.xyz / clip.w;
+	vec2 uv = ndc.xy * 0.5 + 0.5;
+	// Sun shadow map is always rendered with a standard (non-reversed) ortho
+	// projection on the CPU side, so depth lives in [0,1] with 0=near, 1=far.
+	float depth = ndc.z * 0.5 + 0.5;
+	if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0 || depth < 0.0 || depth > 1.0)
+		return 1.0;
+
+	float bias = max(ShadowBiasCounts.y, 0.0);
+	float receiver_bias = max(fwidth(depth), 0.0) * max(ShadowBiasCounts.w, 0.0);
+	bias += receiver_bias;
+	float pcf = max(ShadowPCFTexel.x, 0.0) * max(ShadowPCFTexel.z, 0.0);
+	float sum = 0.0;
+	float taps = 0.0;
+	for (int y = -1; y <= 1; ++y)
+	{
+		for (int x = -1; x <= 1; ++x)
+		{
+			float closest = texture(SunShadowTex, vec3(uv + vec2(float(x), float(y)) * pcf, float(cascade))).r;
+			// Standard map: receiver is lit when its depth (minus bias) is <= stored depth.
+			sum += (depth - bias <= closest) ? 1.0 : 0.0;
+			taps += 1.0;
+		}
+	}
+	return (taps > 0.0) ? (sum / taps) : 1.0;
+}
+
+float SampleSunShadowDepth(vec3 worldPos)
+{
+	if (ShadowEnableDebug.x < 0.5 || ShadowEnableDebug.y < 0.5)
+		return 1.0;
+
+	int cascade = ShadowCascadeForWorldPos(worldPos);
+	vec4 clip = ShadowSunViewProj[cascade] * vec4(worldPos, 1.0);
+	if (abs(clip.w) <= 1e-6)
+		return 1.0;
+
+	vec3 ndc = clip.xyz / clip.w;
+	vec2 uv = ndc.xy * 0.5 + 0.5;
+	if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)
+		return 1.0;
+
+	return texture(SunShadowTex, vec3(uv, float(cascade))).r;
+}
+
+float SampleDLightShadow(int lightIndex, vec3 worldPos, vec3 lightPos, float radius)
+{
+	if (ShadowEnableDebug.x < 0.5 || ShadowEnableDebug.z < 0.5)
+		return 1.0;
+
+	int slot = ShadowSlotForLight(lightIndex);
+	if (slot < 0)
+		return 1.0;
+
+	vec3 dir = worldPos - lightPos;
+	float dist = length(dir);
+	if (dist <= 1e-5 || radius <= 1e-5)
+		return 1.0;
+
+	vec3 dirN = dir / dist;
+	// INVARIANTE: ref = dist/radius wird mit stored = dist_occluder/farPlane verglichen.
+	// Korrekt NUR wenn farPlane (ShadowLightPosFar.w) == radius beim Shadow-Pass.
+	// CPU muss ShadowLightPosFar.w = l.radius setzen — sonst falsche Tiefenvergleiche.
+	float ref = dist / radius;
+	float bias = max(ShadowBiasCounts.z, 0.0);
+	float receiver_bias = max(fwidth(ref), 0.0) * max(ShadowBiasCounts.w, 0.0);
+	bias += receiver_bias;
+	float pcf = max(ShadowPCFTexel.y, 0.0) * max(ShadowPCFTexel.w, 0.0) * 2.0;
+
+	vec3 axis = (abs(dirN.z) < 0.999) ? vec3(0.0, 0.0, 1.0) : vec3(0.0, 1.0, 0.0);
+	vec3 tangent = normalize(cross(axis, dirN));
+	vec3 bitangent = normalize(cross(dirN, tangent));
+	float vis = 0.0;
+	float taps = 0.0;
+	for (int i = 0; i < 4; ++i)
+	{
+		vec2 o = vec2((i & 1) == 0 ? -1.0 : 1.0, (i < 2) ? -1.0 : 1.0) * pcf;
+		vec3 sampleDir = normalize(dirN + tangent * o.x + bitangent * o.y);
+		float closest = texture(DLightShadowTex, vec4(sampleDir, float(slot))).r;
+		vis += (ref - bias <= closest) ? 1.0 : 0.0;
+		taps += 1.0;
+	}
+	return vis / max(taps, 1.0);
+}
+
+float ComputeCombinedDLightShadow(vec3 worldPos)
+{
+	if (ShadowEnableDebug.x < 0.5 || ShadowEnableDebug.z < 0.5)
+		return 1.0;
+
+	int numLights = int(NumLights);
+	float accum = 0.0;
+	float wsum = 0.0;
+	int slots = int(clamp(ShadowBiasCounts.x, 0.0, 4.0));
+	for (int slot = 0; slot < slots; ++slot)
+	{
+		int idx = int(round((slot == 0) ? ShadowDLightIndices.x :
+				    (slot == 1) ? ShadowDLightIndices.y :
+				    (slot == 2) ? ShadowDLightIndices.z : ShadowDLightIndices.w));
+		if (idx < 0 || idx >= numLights)
+			continue;
+		Light l = Lights[idx];
+		vec3 d = worldPos - l.origin;
+		float dist = length(d);
+		if (dist >= l.radius || l.radius <= 1e-5)
+			continue;
+		float w = 1.0 - dist / l.radius;
+		float vis = SampleDLightShadow(idx, worldPos, l.origin, l.radius);
+		accum += vis * w;
+		wsum += w;
+	}
+
+	return (wsum > 1e-6) ? (accum / wsum) : 1.0;
+}
+
+float SampleFirstDLightDepth(vec3 worldPos)
+{
+	if (ShadowEnableDebug.x < 0.5 || ShadowEnableDebug.z < 0.5)
+		return 1.0;
+	if (ShadowBiasCounts.x < 0.5)
+		return 1.0;
+
+	int numLights = int(NumLights);
+	int idx = int(round(ShadowDLightIndices.x));
+	if (idx < 0 || idx >= numLights)
+		return 1.0;
+
+	Light l = Lights[idx];
+	vec3 dir = worldPos - l.origin;
+	float len = length(dir);
+	if (len <= 1e-5)
+		return 1.0;
+
+	return texture(DLightShadowTex, vec4(dir / len, 0.0)).r;
+}
+
+#define OUT_COLOR out_fragcolor
+
+#if OIT
+	vec4 OUT_COLOR;
+	layout(location=0) out vec4 out_accum;
+	layout(location=1) out float out_reveal;
+
+	vec3 GammaToLinear(vec3 v)
+	{
+		return v;
+	}
+
+	void main_body();
+
+	void main()
+	{
+		main_body();
+		OUT_COLOR = clamp(OUT_COLOR, 0.0, 1.0);
+		vec4 color = vec4(GammaToLinear(OUT_COLOR.rgb), OUT_COLOR.a);
+		float z = 1.0 / gl_FragCoord.w;
+		float weight = clamp(color.a * color.a * 0.03 / (1e-5 + pow(z/1e7, 1.0)), 1e-2, 3e3);
+		// WBOIT: weighted-blended OIT (McGuire & Bavoil 2013).
+		// accum.rgb = pre-multiplied color * weight
+		// accum.a   = alpha * weight  (used for normalization in composite pass)
+		// reveal    = 1 - alpha        (product of (1-alpha) across layers)
+		out_accum  = vec4(color.rgb * color.a * weight, color.a * weight);
+		out_reveal = 1.0 - color.a;
+	}
+
+	#define main main_body
+#else
+	layout(location=0) out vec4 OUT_COLOR;
+	layout(location=1) out vec4 out_velocity;
+#endif
+
+void main()
+{
+	vec3 fullbright = vec3(0.0);
+	vec3 emissive   = vec3(0.0);
+	float spec_map_value = 1.0;
+	vec2 uv = in_uv;
+
+#if MODE == 2
+	uv = uv * 2.0 + 0.125 * sin(uv.yx * (3.14159265 * 2.0) + Time);
+#endif
+
+	int tcgen_debug = int(ShaderParams.y + 0.5);
+	if (tcgen_debug > 0 && in_tcgen == TCGEN_ENVIRONMENT)
+	{
+		// BUG FIX: was writing to undeclared "out_fragcolor" alias before OUT_COLOR macro
+		// is set up. Use OUT_COLOR consistently.
+		OUT_COLOR = vec4(fract(uv), 0.0, 1.0);
+#if !OIT
+		out_velocity = vec4(0.0);
+#endif
+		return;
+	}
+
+	// Sample textures
+#if BINDLESS
+	sampler2D Tex = sampler2D(in_samplers0.xy);
+	sampler2D NormalSampler = sampler2D(in_samplers1.zw);
+	if ((in_flags & CF_USE_FULLBRIGHT) != 0u)
+	{
+		sampler2D FullbrightTex = sampler2D(in_samplers0.zw);
+		fullbright = texture(FullbrightTex, uv).rgb;
+	}
+	if ((in_flags & CF_USE_EMISSIVE) != 0u)
+	{
+		sampler2D EmissiveSampler = sampler2D(in_samplers1.xy);
+		emissive = texture(EmissiveSampler, uv).rgb;
+	}
+	if (in_specular.z > 0.5)
+	{
+		sampler2D SpecSampler = sampler2D(in_samplers2.xy);
+		vec4 spec_sample = texture(SpecSampler, uv);
+		spec_map_value = (in_specular.z > 1.5) ? (1.0 - spec_sample.a) : spec_sample.r;
+	}
+#else
+	if ((in_flags & CF_USE_FULLBRIGHT) != 0u)
+		fullbright = texture(FullbrightTex, uv).rgb;
+	if ((in_flags & CF_USE_EMISSIVE) != 0u)
+		emissive = texture(EmissiveTex, uv).rgb;
+	if (in_specular.z > 0.5)
+	{
+		vec4 spec_sample = texture(SpecularTex, uv);
+		spec_map_value = (in_specular.z > 1.5) ? (1.0 - spec_sample.a) : spec_sample.r;
+	}
+#endif
+
+#if DITHER >= 2
+	vec4 result = texture(Tex, uv, -1.0);
+#elif DITHER
+	vec4 result = texture(Tex, uv, -0.5);
+#else
+	vec4 result = texture(Tex, uv);
+#endif
+	vec3 albedo = result.rgb;
+
+#if MODE == 1
+	if (result.a < 0.666)
+		discard;
+#endif
+
+	// --- Debug modes (early-out) ---
+	int debug_mode = int(ColorSpaceParams.x + 0.5);
+	int lighting_debug_view = int(ColorSpaceParams.w + 0.5);
+	if (debug_mode == 1)
+	{
+		// BUG FIX: original wrote to literal "out_fragcolor" which is only a valid
+		// identifier when OIT==0. Use OUT_COLOR (resolves to the correct output in both paths).
+		OUT_COLOR = vec4(result.rgb, 1.0);
+#if !OIT
+		out_velocity = vec4(0.0);
+#endif
+		return;
+	}
+
+	int shader_debug = int(ShaderParams.x + 0.5);
+	if (shader_debug >= 2)
+	{
+		vec3 debug_color = vec3(0.0);
+		if ((in_flags & CF_MAT_BLOOM)    != 0u) debug_color += vec3(1.0, 0.0, 1.0);
+		if ((in_flags & CF_MAT_EMISSIVE) != 0u) debug_color += vec3(1.0, 1.0, 0.0);
+		if ((in_flags & CF_MAT_GODRAY)   != 0u) debug_color += vec3(0.0, 1.0, 1.0);
+		if ((in_flags & CF_MAT_TRANS)    != 0u) debug_color += vec3(0.0, 1.0, 0.0);
+		if ((in_flags & CF_MAT_SKY)      != 0u) debug_color += vec3(0.0, 0.0, 1.0);
+		if (all(lessThanEqual(debug_color, vec3(0.0)))) debug_color = result.rgb;
+		// BUG FIX: same out_fragcolor alias issue
+		OUT_COLOR = vec4(clamp(debug_color, 0.0, 1.0), 1.0);
+#if !OIT
+		out_velocity = vec4(0.0);
+#endif
+		return;
+	}
+
+	bool additive_dlights = (DLightParams.x > 0.5) && (lighting_debug_view == 0);
+
+	// Lightmap sampling
+	vec2 lmuv = in_lmuv;
+	vec3 total_lightmap = vec3(1.0);
+	vec3 specular_light = vec3(0.0);
+	float ndotl_accum = 0.0;
+	float ndotl_weight = 0.0;
+#if DITHER
+	// OPT: compute once, reuse below for dithering
+	vec2 lmsize = vec2(textureSize(LMTex, 0).xy) * 16.0;
+#endif
+
+	// Surface normal (computed early; needed inside and outside lightmap block)
+	vec3 surface_normal = in_normal;
+	vec3 geom_normal = vec3(0.0, 0.0, 1.0);
+	{
+		float surface_normal_len = length(surface_normal);
+		if (surface_normal_len > 0.0)
+		{
+			surface_normal /= surface_normal_len;
+		}
+		else
+		{
+			vec3 gn = cross(dFdx(in_pos), dFdy(in_pos));
+			float gl = length(gn);
+			surface_normal = (gl > 0.0) ? (gn / gl) : vec3(0.0, 0.0, 1.0);
+		}
+		if (!gl_FrontFacing)
+			surface_normal = -surface_normal;
+
+		geom_normal = surface_normal;
+		vec3 tangent = in_tangent.xyz;
+		float tlen = length(tangent);
+#if BINDLESS
+		vec3 sampled_n = texture(NormalSampler, in_uv).xyz * 2.0 - 1.0;
+#else
+		vec3 sampled_n = texture(NormalTex, in_uv).xyz * 2.0 - 1.0;
+#endif
+		bool has_nm = dot(sampled_n.xy, sampled_n.xy) > 1e-5;
+		if (tlen > 1e-5 && has_nm)
+		{
+			vec3 T = tangent / tlen;
+			vec3 B = normalize(cross(geom_normal, T)) * sign(in_tangent.w);
+			mat3 TBN = mat3(T, B, geom_normal);
+			surface_normal = normalize(TBN * normalize(sampled_n));
+		}
+	}
+
+	// View direction (computed once; used by specular lighting)
+	vec3 to_eye    = EyePos - in_pos;
+	float view_len = length(to_eye);
+	// OPT: avoid normalize() call by inlining division guard
+	vec3 view_dir  = (view_len > 0.0) ? (to_eye / view_len) : vec3(0.0, 0.0, 1.0);
+	float rim_factor = 0.0;
+	if (RimLightParams0.x > 0.5 && RimLightParams1.x > 0.5)
+	{
+		float rim_ndotv = 1.0 - clamp(dot(surface_normal, view_dir), 0.0, 1.0);
+		rim_factor = pow(max(rim_ndotv, 0.0), max(RimLightParams0.z, 0.5)) * max(RimLightParams0.y, 0.0);
+	}
+	vec3 rim_dlight_accum = vec3(0.0);
+	vec3 rim_sun_accum = vec3(0.0);
+
+	if ((in_flags & CF_NOLIGHTMAP) == 0u)
+	{
+#if DITHER
+		lmuv = (floor(lmuv * lmsize) + 0.5) / lmsize;
+#endif
+
+		vec4 lm0 = SampleLightmap(lmuv);
+		vec3 static_light;
+
+		if (in_styles.y < 0.0) // Single style fast path
+		{
+			static_light = in_styles.x * lm0.xyz;
+		}
+		else
+		{
+			vec4 lm1 = SampleLightmap(vec2(lmuv.x + in_lmofs, lmuv.y));
+			if (in_styles.z < 0.0) // 2 styles
+			{
+				static_light = in_styles.x * lm0.xyz + in_styles.y * lm1.xyz;
+			}
+			else // 3 or 4 lightstyles
+			{
+				vec4 lm2 = SampleLightmap(vec2(lmuv.x + in_lmofs * 2.0, lmuv.y));
+				// FIX: dot(in_styles, lmN) war falsch - lmN.w ist Lightmap-Alpha,
+				// kein Lightstyle-Gewicht. Korrekter style-gewichteter Sum. lm3 fuer 4 Styles.
+				if (in_styles.w < 0.0) // 3 styles
+				{
+					static_light = in_styles.x * lm0.xyz
+					             + in_styles.y * lm1.xyz
+					             + in_styles.z * lm2.xyz;
+				}
+				else // 4 styles
+				{
+					vec4 lm3 = SampleLightmap(vec2(lmuv.x + in_lmofs * 3.0, lmuv.y));
+					static_light = in_styles.x * lm0.xyz
+					             + in_styles.y * lm1.xyz
+					             + in_styles.z * lm2.xyz
+					             + in_styles.w * lm3.xyz;
+				}
+			}
+		}
+
+		// Sun-Shadow entfernt: Sonne ist keine Lichtquelle mehr.
+		// DLight-Schatten werden ausschliesslich in world_dlight.frag pro Licht berechnet.
+		// static_light geht ungekürzt in total_light ein.
+
+		vec3 lightgrid   = mix(vec3(1.0), in_lightgrid, LightgridParams.x);
+
+		if (LightgridParams.y > 0.5)
+		{
+			OUT_COLOR = vec4(lightgrid, 1.0);
+#if !OIT
+			out_velocity = vec4(0.0);
+#endif
+			return;
+		}
+
+		if (LightgridParams.w > 0.5)
+		{
+			float skyvis_debug = clamp(in_skyvisibility, 0.0, 1.0);
+			OUT_COLOR = vec4(vec3(skyvis_debug), 1.0);
+#if !OIT
+			out_velocity = vec4(0.0);
+#endif
+			return;
+		}
+
+		// Directional lightmap
+		if (LightmapParams.z > 0.5)
+		{
+			vec3 dir = SampleLightmapDir(lmuv);
+			// BUG FIX: was dot(dir, vec3(0,0,1)) — must use the actual surface
+			// normal so slanted geometry is shaded correctly.
+			float ndl = max(dot(dir, surface_normal), 0.0);
+			static_light *= ndl;
+		}
+
+		if (LightmapParams.x > 0.5)
+		{
+			vec3 static_light_debug = static_light;
+			OUT_COLOR = vec4(clamp(static_light_debug, 0.0, 1.0), 1.0);
+#if !OIT
+			out_velocity = vec4(0.0);
+#endif
+			return;
+		}
+
+		vec3 clamped_static = clamp(static_light, 0.0, 1.0);
+		/* Lightgrid probes are intended for dynamic/model relighting.
+		 * Applying them multiplicatively to baked world lightmaps can over-darken
+		 * indoor scenes (double attenuation). Keep world static lighting authored. */
+		vec3 total_light    = clamped_static + in_bmodel_relight;
+		float sky_visibility = clamp(in_skyvisibility, 0.0, 1.0);
+		float sky_upness = clamp(surface_normal.z * 0.5 + 0.5, 0.0, 1.0);
+		float sky_room = 1.0 - 0.6 * max(max(clamped_static.r, clamped_static.g), clamped_static.b);
+		vec3 sky_diffuse = AmbientSkyDiffuse(sky_visibility, sky_upness, sky_room);
+		total_light += max(min(sky_diffuse, 1.0 - total_light), 0.0);
+
+		// Dynamic lights
+		if (!additive_dlights && NumLights > 0u)
+		{
+			vec3  dynamic_light      = vec3(0.0);
+			uvec3 tile_coord = ComputeLightTileCoord(in_coord, max(in_depth, 1e-6));
+			float dynamic_light_noise = 1.0 - whitenoise01(in_pos.xy) * 0.15;
+			// OPT: precompute plane dot-product once outside loop
+			vec4 plane = vec4(surface_normal, dot(in_pos, surface_normal));
+
+			for (uint light_index = 0u; light_index < NumLights; light_index++)
+			{
+				Light l = Lights[light_index];
+
+				float rad  = l.radius;
+				float dist = dot(l.origin, plane.xyz) - plane.w;
+				rad -= abs(dist);
+				float minlight = l.minlight;
+
+				if (rad <= 0.0 || rad < minlight)
+					continue;
+
+				vec3  local_pos = l.origin - plane.xyz * dist;
+				minlight = rad - minlight;
+				vec3  light_vec = local_pos - in_pos;
+				float dist_sq = dot(light_vec, light_vec);
+
+				// OPT: keep rsqrt path ready for clustered lists where this loop gets shorter.
+				if (dist_sq < 1e-12)
+					continue;
+				float inv_surface_dist = inversesqrt(dist_sq);
+				float surface_dist = dist_sq * inv_surface_dist;
+
+				float attenuation   = clamp((minlight - surface_dist) * (1.0/16.0), 0.0, 1.0);
+				float normalized_d  = surface_dist / rad;
+				// OPT: pow(x,1.5) = x*sqrt(x), avoids generic pow()
+				float nc            = clamp(1.0 - normalized_d, 0.0, 1.0);
+				float falloff       = nc * sqrt(nc);
+				float shadow = SampleDLightShadow(int(light_index), in_pos, l.origin, l.radius);
+				vec3  light_contrib = attenuation * falloff * shadow * l.color * dynamic_light_noise;
+
+				// FIX: Shadow-Term fuer dieses DLight berechnen.
+				// War faelschlicherweise entfernt - keine DLight-Schatten in world.frag.
+
+				dynamic_light      += light_contrib;
+				if (rim_factor > 1e-5 && RimLightParams1.w > 0.0)
+				{
+					float rim_shadow = (RimLightParams0.w > 0.5) ? shadow : 1.0;
+					vec3 light_dir = light_vec * inv_surface_dist;
+					float backlight = mix(0.35, 1.0, max(dot(-surface_normal, light_dir), 0.0));
+					rim_dlight_accum += (attenuation * falloff) * rim_shadow * l.color * dynamic_light_noise * backlight;
+				}
+
+				// Specular
+				if (attenuation > 0.0 && falloff > 0.0)
+				{
+					vec3  light_dir = light_vec * inv_surface_dist;      // already normalised
+					float ndotl     = max(dot(surface_normal, light_dir), 0.0);
+					float light_weight = attenuation * falloff * shadow;
+					ndotl_accum += ndotl * light_weight;
+					ndotl_weight += light_weight;
+
+					if (ndotl > 0.0)
+					{
+						vec3  half_vec = normalize(light_dir + view_dir); // OPT: single normalize
+						float ndoth    = max(dot(surface_normal, half_vec), 0.0);
+						// SPECULAR_POWER=16 -> pow(x,16) = ((x*x)*(x*x))*((x*x)*(x*x)) — two squarings
+						float h2  = ndoth * ndoth;
+						float h4  = h2 * h2;
+						float h8  = h4 * h4;
+						float h16 = h8 * h8; // legacy x^16 baseline
+						float spec_exp = max(in_specular.y, 1.0);
+						float legacy_to_exp = pow(max(h16, 0.0), spec_exp * (1.0 / 16.0));
+						float spec = legacy_to_exp * ndotl;
+						float spec_scale = max(in_specular.x, 0.0) * clamp(spec_map_value, 0.0, 1.0);
+						specular_light += light_contrib * spec * spec_scale;
+					}
+				}
+			}
+
+			// OPT: clamp(x, 0, 1-total_light) saturates without overflow
+			total_light += max(min(dynamic_light, 1.0 - total_light), 0.0);
+		}
+
+		// Sun light
+		if (SunDirEnabled.w > 0.5)
+		{
+			/* SunDirEnabled.xyz stores scene->sun direction. Surface lighting needs
+			 * incoming-light direction (sun->scene), therefore we negate it. */
+			vec3 sun_to_surface = -SunDirEnabled.xyz;
+			/* Legacy fallback fill for non-sky surfaces. This keeps old map
+			 * readability when SkyVis data is sparse or unavailable. */
+			float sun_visibility = ((in_flags & CF_MAT_SKY) != 0u) ? 1.0 : ShaderParams.z;
+			float ndotl = max(dot(surface_normal, sun_to_surface), 0.0);
+			if (ndotl > 0.0)
+			{
+				float sun_shadow = SampleSunShadow(in_pos);
+				vec3 sun_contrib = SunColorIntensity.rgb * SunColorIntensity.a * ndotl * sun_visibility * sun_shadow;
+				total_light += max(min(sun_contrib, 1.0 - total_light), 0.0);
+				if (rim_factor > 1e-5 && RimLightParams1.z > 0.0)
+				{
+					float rim_shadow = (RimLightParams0.w > 0.5) ? sun_shadow : 1.0;
+					float sun_back = max(dot(-surface_normal, sun_to_surface), 0.0);
+					rim_sun_accum += SunColorIntensity.rgb * SunColorIntensity.a
+						* sun_visibility * rim_shadow * mix(0.35, 1.0, sun_back);
+				}
+			}
+			else if (rim_factor > 1e-5 && RimLightParams1.z > 0.0)
+			{
+				float rim_shadow = (RimLightParams0.w > 0.5) ? SampleSunShadow(in_pos) : 1.0;
+				float sun_back = max(dot(-surface_normal, sun_to_surface), 0.0);
+				rim_sun_accum += SunColorIntensity.rgb * SunColorIntensity.a
+					* sun_visibility * rim_shadow * mix(0.35, 1.0, sun_back);
+			}
+		}
+
+		// Apply lighting
+#if DITHER >= 2
+		vec3 clamped_light = clamp(total_light, 0.0, 1.0);
+		total_lightmap = clamp(floor(clamped_light * 63.0 + 0.5) * (Overbright / 63.0), 0.0, Overbright);
+#else
+		total_lightmap = clamp(total_light * Overbright, 0.0, Overbright);
+#endif
+	} // end lightmap block
+
+	// Apply lightmap to albedo
+#if MODE != 1
+	// Fallback for bmodels without baked lightmaps: CPU fills in_bmodel_relight with
+	// sampled static world lighting (0..1). This avoids black pickup boxes.
+	if ((in_flags & CF_NOLIGHTMAP) != 0u && dot(in_bmodel_relight, in_bmodel_relight) > 1e-6)
+		total_lightmap = clamp(in_bmodel_relight * Overbright, 0.0, Overbright);
+	result.rgb = mix(result.rgb, result.rgb * total_lightmap, result.a);
+#else
+	if ((in_flags & CF_NOLIGHTMAP) != 0u && dot(in_bmodel_relight, in_bmodel_relight) > 1e-6)
+		total_lightmap = clamp(in_bmodel_relight * Overbright, 0.0, Overbright);
+	result.rgb *= total_lightmap;
+#endif
+
+	result.rgb += fullbright + emissive;
+
+	// Add specular
+	result.rgb += clamp(specular_light, vec3(0.0), vec3(Overbright)) * clamp(result.a, 0.0, 1.0);
+	if (rim_factor > 1e-5)
+	{
+		vec3 rim_light = rim_sun_accum * RimLightParams1.z + rim_dlight_accum * RimLightParams1.w;
+		result.rgb += result.rgb * rim_light * rim_factor;
+	}
+
+	if (CausticsParams0.x > 0.5 && MODE != 2 && (in_flags & CF_MAT_SKY) == 0u)
+	{
+		float caustic_term = 0.0;
+		float intensity = max(CausticsParams0.z, 0.0);
+		float scale = max(CausticsParams0.w, 1e-4);
+		float speed = max(CausticsParams1.x, 0.0);
+		float up = clamp(geom_normal.z, 0.0, 1.0);
+		float wallness = 1.0 - up;
+		float floor_mask = smoothstep(0.45, 0.88, up);
+		float wall_mask = smoothstep(0.08, 0.95, wallness) * 0.62;
+		float surface_mask = clamp(max(floor_mask, wall_mask), 0.0, 1.0);
+		float light_mask = clamp(dot(total_lightmap, vec3(0.3333333)) / max(Overbright, 1e-4), 0.0, 1.0);
+		int medium = int(CausticsParams0.y + 0.5);
+
+		if (medium == 1) // water
+		{
+			float pattern = WaterCausticPattern(in_pos, geom_normal, scale, speed);
+			float floor_light = 0.55 + 0.45 * light_mask;
+			float wall_light  = 0.82 + 0.18 * light_mask;
+			float orient      = smoothstep(0.22, 0.85, wallness);
+			float water_mask  = surface_mask * mix(floor_light, wall_light, orient);
+			caustic_term      = pattern * water_mask;
+
+			// Multiply component: brightens the focal lines naturally
+			result.rgb *= 1.0 + caustic_term * intensity * 0.22;
+
+			// Additive component: chromatic fringe (focal lines skew slightly blue-cyan)
+			// R channel gets slightly less energy than G/B, mimicking real water dispersion.
+			vec3 caustic_tint = vec3(
+				0.008 + 0.004 * (1.0 - pattern),   // red: dimmer outside lines
+				0.018 + 0.006 * pattern,             // green: tracks focal peaks
+				0.030 + 0.010 * pattern);             // blue: strongest at focal peaks
+			result.rgb += caustic_tint * caustic_term * intensity;
+
+			// Subtle global cool tint on the full surface (underwater ambient scatter)
+			result.rgb += vec3(0.0, 0.003, 0.006) * water_mask * intensity * 0.5;
+		}
+		else if (medium == 2) // lava
+		{
+			float pattern = LavaHeatPattern(in_pos, scale, speed * 0.6);
+			caustic_term = pattern * mix(0.45, 1.0, surface_mask);
+			result.rgb += vec3(1.0, 0.38, 0.08) * caustic_term * intensity * 0.40;
+		}
+
+		if (CausticsParams1.y > 1.5)
+		{
+			vec3 dbg = vec3(caustic_term);
+			OUT_COLOR = vec4(dbg, 1.0);
+#if !OIT
+			out_velocity = vec4(0.0);
+#endif
+			return;
+		}
+		else if (CausticsParams1.y > 0.5)
+			result.rgb = vec3(caustic_term);
+	}
+
+	result.rgb = SanitizeColor(result.rgb);
+	vec3 pre_tonemap_hdr = result.rgb;
+
+	// Tone mapping is handled in postprocess only.
+
+	result.rgb  *= in_stage_color.rgb;
+	result.a     = in_alpha * in_stage_color.a;
+	result       = clamp(result, 0.0, 1.0);
+	float fog_att = FogAttenuation(in_pos - EyePos);
+
+	if (lighting_debug_view > 0)
+	{
+		vec3 debug_rgb = result.rgb;
+		if (lighting_debug_view == 1)
+		{
+			debug_rgb = clamp(albedo, 0.0, 1.0);
+		}
+		else if (lighting_debug_view == 2)
+		{
+			vec3 light_vis = total_lightmap / max(Overbright, 1e-4);
+			debug_rgb = clamp(light_vis, 0.0, 1.0);
+		}
+		else if (lighting_debug_view == 3)
+		{
+			float ndotl_vis = (ndotl_weight > 1e-5) ? (ndotl_accum / ndotl_weight) : 0.0;
+			debug_rgb = vec3(clamp(ndotl_vis, 0.0, 1.0));
+		}
+		else if (lighting_debug_view == 4)
+		{
+			debug_rgb = surface_normal * 0.5 + 0.5;
+		}
+		else if (lighting_debug_view == 5)
+		{
+			debug_rgb = clamp(specular_light / max(Overbright, 1e-4), 0.0, 1.0);
+		}
+		else if (lighting_debug_view == 6)
+		{
+			debug_rgb = vec3(clamp(in_skyvisibility, 0.0, 1.0));
+		}
+		else if (lighting_debug_view == 7)
+		{
+			debug_rgb = vec3(clamp(1.0 - fog_att, 0.0, 1.0));
+		}
+		else if (lighting_debug_view == 8)
+		{
+			debug_rgb = clamp(log2(vec3(1.0) + max(pre_tonemap_hdr, vec3(0.0))) * 0.25, 0.0, 1.0);
+		}
+
+		result.rgb = debug_rgb;
+		result.a = 1.0;
+		OUT_COLOR = result;
+#if !OIT
+		out_velocity = vec4(0.0);
+#endif
+		return;
+	}
+
+	if (ShadowEnableDebug.w > 0.5)
+	{
+		int smode = int(ShadowEnableDebug.w + 0.5);
+		if (smode == 1)
+			result.rgb = vec3(SampleSunShadow(in_pos));
+		else if (smode == 2)
+			result.rgb = vec3(ComputeCombinedDLightShadow(in_pos));
+		else if (smode == 3)
+			result.rgb = vec3(SampleSunShadowDepth(in_pos));
+		else if (smode == 4)
+			result.rgb = vec3(SampleFirstDLightDepth(in_pos));
+		else if (smode == 5)
+		{
+			int ci = ShadowCascadeForWorldPos(in_pos);
+			const vec3 cascade_colors[4] = vec3[4](
+				vec3(1.0, 0.25, 0.25),
+				vec3(0.25, 1.0, 0.25),
+				vec3(0.25, 0.5, 1.0),
+				vec3(1.0, 0.85, 0.25));
+			result.rgb = cascade_colors[clamp(ci, 0, 3)];
+		}
+	}
+
+	result.rgb   = mix(Fog.rgb, result.rgb, fog_att);
+	result.rgb   = SanitizeColor(result.rgb);
+
+	// BUG FIX: original wrote "out_fragcolor" directly but OUT_COLOR must be used
+	// to stay compatible with both OIT and non-OIT paths.
+	OUT_COLOR = result;
+
+#if !OIT
+	vec2 velocity    = ComputeVelocity(in_curr_clip, in_prev_clip);
+	// BUG FIX: original condition (result.a >= 0.999) wrote velocity * result.a, but
+	// result.a is already >=0.999 ~= 1; just write velocity directly to avoid
+	// subtle sub-pixel ghosting on nearly-opaque geometry.
+	vec2 velocityOut = (result.a >= 0.999) ? velocity : vec2(0.0);
+	float materialMask = ((in_flags & CF_MAT_BLOOM)    != 0u) ? 1.0 : 0.0;
+	if  ((in_flags & CF_MAT_EMISSIVE) != 0u) materialMask += 4.0;
+	if  ((in_flags & CF_MAT_TRANS)    != 0u) materialMask += 2.0;
+	out_velocity = vec4(velocityOut, 0.0, materialMask);
+#endif
+
+	// Dithering
+#if DITHER == 1
+	vec3  dpos    = fwidth(in_pos);
+	float farblend = clamp(max(dpos.x, max(dpos.y, dpos.z)) * 0.5 - 0.125, 0.0, 1.0);
+	farblend *= farblend;
+	// OPT: sqrt then square — work in sqrt-luminance space for perceptual dither
+	OUT_COLOR.rgb = sqrt(OUT_COLOR.rgb);
+	float luma     = dot(OUT_COLOR.rgb, vec3(0.25, 0.625, 0.125));
+	float nearnoise = tri(whitenoise01(lmuv * lmsize)) * luma * TextureDither;
+	float farnoise  = (abs(Fog.w) > 0.0) ? SCREEN_SPACE_NOISE() * ScreenDither : 0.0;
+	OUT_COLOR.rgb  += mix(nearnoise, farnoise, farblend);
+	OUT_COLOR.rgb  *= OUT_COLOR.rgb;
+#endif
+
+#if DITHER >= 2
+	OUT_COLOR.rgb = floor(OUT_COLOR.rgb * 255.0 + 0.5) * (1.0/255.0);
+#elif DITHER == 0
+	OUT_COLOR.rgb += SUPPRESS_BANDING() * ScreenDither;
+#endif
+}

Index: pakfiles/shaders/world.vert
===================================================================
--- pakfiles/shaders/world.vert	
+++ pakfiles/shaders/world.vert	
@@ -0,0 +1,292 @@
+#if BINDLESS
+	#extension GL_ARB_shader_draw_parameters : require
+	#define DRAW_ID gl_DrawIDARB
+#else
+	layout(location=0) uniform int DrawID;
+	#define DRAW_ID DrawID
+#endif
+
+#include "frame_uniforms.glsl"
+
+// Fog.w is treated as a signed-friendly density; use abs(Fog.w) so negative CPU values do not invert attenuation.
+vec3 ApplyFog(vec3 clr, vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	fog = clamp(fog, 0.0, 1.0);
+	return mix(Fog.rgb, clr, fog);
+}
+
+#define LIGHT_TILES_X 32
+#define LIGHT_TILES_Y 16
+#define LIGHT_TILES_Z 32
+#define MAX_LIGHTS    64
+
+struct Light
+{
+	vec3	origin;
+	float	radius;
+	vec3	color;
+	float	minlight;
+};
+
+layout(std430, binding=0) restrict readonly buffer LightBuffer
+{
+	vec2	LightStyles[64];
+	Light	Lights[];
+};
+
+// OPT: ternary version is more GPU-friendly than if/else (avoids branch divergence)
+float GetLightStyle(int index)
+{
+	return (index < 64) ? mix(LightStyles[index].x, LightStyles[index].y, LightmapParams.w) : 1.0;
+}
+
+struct Call
+{
+	uint	flags;
+	uint	tcgen;
+	float	wateralpha;
+	int		spec_mode;
+	vec2	polygon_offset;
+	vec2	specular; // x=intensity y=exponent
+	vec4	stage_color;
+#if BINDLESS
+	uvec2	txhandle;
+	uvec2	fbhandle;
+	uvec2	emhandle;
+	uvec2	nmhandle;
+	uvec2	smhandle;
+#else
+	int		baseinstance;
+	int		padding[3];
+#endif
+};
+
+const uint
+	CF_USE_POLYGON_OFFSET = 1u,
+	CF_USE_FULLBRIGHT     = 2u,
+	CF_NOLIGHTMAP         = 4u,
+	CF_USE_EMISSIVE       = 8u,
+	CF_ALPHA_TEST         = 16u;
+
+const uint
+	TCGEN_BASE        = 0u,
+	TCGEN_LIGHTMAP    = 1u,
+	TCGEN_ENVIRONMENT = 2u;
+
+layout(std430, binding=1) restrict readonly buffer CallBuffer
+{
+	Call call_data[];
+};
+
+#if BINDLESS
+	#define GET_INSTANCE_ID(call) (gl_BaseInstanceARB + gl_InstanceID)
+#else
+	#define GET_INSTANCE_ID(call) (call.baseinstance + gl_InstanceID)
+#endif
+
+struct Instance
+{
+	vec4	mat[3];
+	vec4	prev_mat[3];
+	float	alpha;
+	float	pad0;
+	float	pad1;
+	float	pad2;
+};
+
+layout(std430, binding=2) restrict readonly buffer InstanceBuffer
+{
+	Instance instance_data[];
+};
+
+// OPT: shared helper avoids duplicating transpose(mat3x4(...)) in Transform/TransformPrev/TransformDirection
+mat4x3 BuildWorldMatrix(vec4 mat[3])
+{
+	return transpose(mat3x4(mat[0], mat[1], mat[2]));
+}
+
+vec3 TransformPosition(vec3 p, vec4 mat[3])
+{
+	return (BuildWorldMatrix(mat) * vec4(p, 1.0)).xyz;
+}
+
+vec3 Transform(vec3 p, Instance instance)
+{
+	return TransformPosition(p, instance.mat);
+}
+
+vec3 TransformPrev(vec3 p, Instance instance)
+{
+	return TransformPosition(p, instance.prev_mat);
+}
+
+// BUG FIX: TransformDirection must use w=0 to suppress translation — was correct,
+// but the inline mat4x3 rebuild was redundant. Now reuses BuildWorldMatrix.
+vec3 TransformDirection(vec3 n, Instance instance)
+{
+	return (BuildWorldMatrix(instance.mat) * vec4(n, 0.0)).xyz;
+}
+
+// Vertex inputs
+layout(location=0) in vec3   in_pos;
+layout(location=1) in vec4   in_uv;       // xy = base UV, zw = lightmap UV
+layout(location=2) in float  in_lmofs;
+layout(location=3) in ivec4  in_styles;
+layout(location=4) in vec3   in_normal;
+layout(location=5) in vec4   in_tangent;
+layout(location=6) in vec3   in_lightgrid;
+layout(location=7) in float  in_skyvisibility;
+
+// Vertex outputs
+layout(location=0)  flat out uint  out_flags;
+layout(location=1)  flat out float out_alpha;
+layout(location=2)  out vec3  out_pos;
+#if MODE == 1
+	layout(location=3) centroid out vec2 out_uv;
+#else
+	layout(location=3) out vec2 out_uv;
+#endif
+layout(location=4)  centroid out vec2 out_lmuv;
+layout(location=5)  out float out_depth;
+layout(location=6)  noperspective out vec2 out_coord;
+layout(location=7)  flat out vec4  out_styles;
+layout(location=8)  flat out float out_lmofs;
+#if BINDLESS
+	layout(location=9)  flat out uvec4 out_samplers0;
+	layout(location=10) flat out uvec4 out_samplers1;
+	layout(location=11) flat out uvec4 out_samplers2;
+#endif
+layout(location=12) noperspective out vec4 out_curr_clip;
+layout(location=13) noperspective out vec4 out_prev_clip;
+layout(location=14) out vec3 out_normal;
+layout(location=15) out vec4 out_tangent;
+layout(location=16) out vec3 out_lightgrid;
+layout(location=17) out float out_skyvisibility;
+layout(location=18) flat out vec4 out_stage_color;
+layout(location=19) flat out uint out_tcgen;
+layout(location=20) flat out vec3 out_bmodel_relight;
+layout(location=21) flat out vec4 out_specular; // x=intensity y=exponent z=mode
+
+vec2 ComputeEnvUV(vec3 world_pos, vec3 world_normal)
+{
+	// OPT: normalize(EyePos - world_pos) can be written as normalize(to_eye)
+	// where to_eye is already computed in main; inlined here for self-containment.
+	vec3 view_dir  = normalize(EyePos - world_pos);
+	vec3 refl      = reflect(-view_dir, normalize(world_normal));
+	vec3 refl_view = mat3(View) * refl;
+	// OPT: replace 3-mul sqrt with dot product (length² then rsqrt is equivalent)
+	float rz1  = refl_view.z + 1.0;
+	float m    = 2.0 * sqrt(dot(refl_view.xy, refl_view.xy) + rz1 * rz1);
+	return refl_view.xy / max(m, 1e-6) + 0.5;
+}
+
+void main()
+{
+	Call     call        = call_data[DRAW_ID];
+	int      instance_id = GET_INSTANCE_ID(call);
+	Instance instance    = instance_data[instance_id];
+
+	// OPT: build world matrix once; reuse for pos + normal transforms
+	mat4x3 world_mat = BuildWorldMatrix(instance.mat);
+	vec3 world_pos   = (world_mat * vec4(in_pos, 1.0)).xyz;
+	// BUG FIX: normal must use w=0 (no translation); was correct before but now explicit
+	vec3 world_normal = (world_mat * vec4(in_normal, 0.0)).xyz;
+
+	vec3 prev_world_pos = TransformPrev(in_pos, instance);
+
+	vec4 curr_clip = ViewProj     * vec4(world_pos,      1.0);
+	vec4 prev_clip = PrevViewProj * vec4(prev_world_pos, 1.0);
+
+#if REVERSED_Z
+	const float ZBIAS = -1.0/1024.0;
+#else
+	const float ZBIAS =  1.0/1024.0;
+#endif
+
+	if ((call.flags & CF_USE_POLYGON_OFFSET) != 0u)
+	{
+		float zoffset = (call.polygon_offset.x + call.polygon_offset.y) * ZBIAS;
+		curr_clip.z += zoffset;
+		prev_clip.z += zoffset;
+	}
+
+	gl_Position   = curr_clip;
+	out_curr_clip = curr_clip;
+	out_prev_clip = prev_clip;
+	out_pos       = world_pos;
+
+	// BUG FIX: original called normalize(world_normal) which is correct, but only after
+	// the rebuild via TransformDirection. Now reusing world_mat directly guarantees
+	// consistent results. normalize() still required — non-uniform scale possible.
+	out_normal    = normalize(world_normal);
+	{
+		vec3 world_tangent = (world_mat * vec4(in_tangent.xyz, 0.0)).xyz;
+		float tangent_len = length(world_tangent);
+		if (tangent_len > 0.0)
+			world_tangent /= tangent_len;
+		out_tangent = vec4(world_tangent, in_tangent.w);
+	}
+	out_lightgrid = in_lightgrid;
+	out_skyvisibility = in_skyvisibility;
+	out_bmodel_relight = vec3(instance.pad0, instance.pad1, instance.pad2);
+
+	// UV selection
+	vec2 uv = in_uv.xy;
+	if      (call.tcgen == TCGEN_LIGHTMAP)    uv = in_uv.zw;
+	else if (call.tcgen == TCGEN_ENVIRONMENT) uv = ComputeEnvUV(world_pos, world_normal);
+	out_uv   = uv;
+	out_lmuv = in_uv.zw;
+
+	out_depth = gl_Position.w;
+
+	// OPT: one reciprocal shared for both xy and coord
+	float inv_w = 1.0 / gl_Position.w;
+	out_coord   = (gl_Position.xy * inv_w * 0.5 + 0.5) * vec2(LIGHT_TILES_X, LIGHT_TILES_Y);
+
+	out_flags = call.flags;
+
+#if MODE == 2
+	out_alpha = instance.alpha < 0.0 ? call.wateralpha : instance.alpha;
+#else
+	out_alpha = instance.alpha < 0.0 ? 1.0 : instance.alpha;
+#endif
+
+	// Light styles
+	out_styles.x = GetLightStyle(in_styles.x);
+	if (in_styles.y == 255)
+	{
+		out_styles.yzw = vec3(-1.0);
+	}
+	else if (in_styles.z == 255)
+	{
+		out_styles.yzw = vec3(GetLightStyle(in_styles.y), -1.0, -1.0);
+	}
+	else
+	{
+		out_styles.y = GetLightStyle(in_styles.y);
+		out_styles.z = GetLightStyle(in_styles.z);
+		out_styles.w = (in_styles.w == 255) ? -1.0 : GetLightStyle(in_styles.w);
+	}
+
+	// BUG FIX: CF_NOLIGHTMAP override must come AFTER style computation;
+	// original order was correct, preserved here.
+	if ((call.flags & CF_NOLIGHTMAP) != 0u)
+		out_styles.xy = vec2(1.0, -1.0);
+
+	out_lmofs       = in_lmofs;
+	out_stage_color = call.stage_color;
+	out_tcgen       = call.tcgen;
+	out_specular    = vec4(call.specular, float(call.spec_mode), 0.0);
+
+#if BINDLESS
+	out_samplers0.xy = call.txhandle;
+	// OPT: branch avoidance: always write fbhandle; fallback to txhandle if no fullbright
+	// This is a known-safe pattern on most drivers.
+	out_samplers0.zw = ((call.flags & CF_USE_FULLBRIGHT) != 0u) ? call.fbhandle : call.txhandle;
+	out_samplers1.xy = call.emhandle;
+	out_samplers1.zw = call.nmhandle;
+	out_samplers2.xy = call.smhandle;
+	out_samplers2.zw = uvec2(0u);
+#endif
+}

Index: pakfiles/shaders/world_dlight.frag
===================================================================
--- pakfiles/shaders/world_dlight.frag	
+++ pakfiles/shaders/world_dlight.frag	
@@ -0,0 +1,371 @@
+#if BINDLESS
+#extension GL_ARB_bindless_texture : require
+#else
+layout(binding=0) uniform sampler2D Tex;
+#endif
+layout(binding=2) uniform sampler2D LMTex; // unused, kept for binding slot consistency
+layout(binding=3) uniform sampler2D LMTexDir; // unused
+layout(binding=7) uniform sampler2DArray SunShadowTex; // reserved for interface parity
+layout(binding=8) uniform samplerCubeArray DLightShadowTex;
+
+#include "frame_uniforms.glsl"
+
+#ifndef ALPHATEST
+#define ALPHATEST 0
+#endif
+
+layout(location=0) uniform float DLightScale;
+layout(location=1) uniform float DLightLumaClamp;
+layout(location=2) uniform float DLightSoftKnee;
+
+layout(location=34) uniform vec4 ShadowEnableDebug;   // x=enabled, y=sun, z=dlight, w=debug mode
+layout(location=35) uniform vec4 ShadowDLightIndices; // selected light indices (float encoded ints)
+layout(location=36) uniform vec4 ShadowBiasCounts;    // x=num dlight slots, y=sun bias, z=dlight bias
+layout(location=37) uniform vec4 ShadowPCFTexel;      // x=sun pcf radius, y=dlight pcf radius, z=1/sun size, w=1/dlight size
+layout(location=45) uniform vec4 RimLightParams0; // x=enable, y=intensity, z=power, w=shadowed
+layout(location=46) uniform vec4 RimLightParams1; // x=world_enable, y=model_enable, z=sun_scale, w=dlight_scale
+
+float FogAttenuation(vec3 p)
+{
+	float fog = exp2(-abs(Fog.w) * dot(p, p));
+	return clamp(fog, 0.0, 1.0);
+}
+
+float SanitizeScalar(float x)
+{
+	return (x == x) ? clamp(x, 0.0, 65504.0) : 0.0;
+}
+
+vec3 SanitizeColor(vec3 color)
+{
+	return vec3(
+		SanitizeScalar(color.x),
+		SanitizeScalar(color.y),
+		SanitizeScalar(color.z));
+}
+
+vec3 ApplyLumaClamp(vec3 color, float lumaClamp)
+{
+	float max_luma = max(lumaClamp, 0.0);
+	if (max_luma <= 0.0)
+		return vec3(0.0);
+
+	float luma = dot(color, vec3(0.299, 0.587, 0.114));
+	if (luma <= max_luma || luma <= 1e-6)
+		return color;
+	return color * (max_luma / luma);
+}
+
+#define MAX_LIGHTS    64
+#define LIGHT_TILES_X 32
+#define LIGHT_TILES_Y 16
+#define LIGHT_TILES_Z 32
+
+struct Light
+{
+	vec3    origin;
+	float   radius;
+	vec3    color;
+	float   minlight;
+};
+
+layout(std430, binding=0) restrict readonly buffer LightBuffer
+{
+	vec2    LightStyles[64];
+	Light   Lights[];
+};
+
+layout(std430, binding=9) restrict readonly buffer LightTileBuffer
+{
+	uvec2 LightTileRanges[];
+};
+
+layout(std430, binding=10) restrict readonly buffer LightTileIndexBuffer
+{
+	uint LightTileIndices[];
+};
+
+layout(location=0) flat in uint in_flags;
+layout(location=1) flat in float in_alpha;
+layout(location=2) in vec3 in_pos;
+layout(location=3) in vec2 in_uv;
+layout(location=4) in float in_depth;
+layout(location=5) noperspective in vec2 in_coord;
+layout(location=6) in vec3 in_normal;
+#if BINDLESS
+layout(location=7) flat in uvec4 in_samplers0;
+layout(location=8) flat in uvec2 in_samplers1;
+#endif
+
+layout(location=0) out vec4 out_fragcolor;
+layout(location=1) out vec4 out_velocity;
+
+float whitenoise01(vec2 p)
+{
+	vec3 p3 = fract(vec3(p.xyx) * 0.1031);
+	p3 += dot(p3, p3.yzx + 33.33);
+	return fract((p3.x + p3.y) * p3.z);
+}
+
+float ComputeFalloff(float x)
+{
+	return x * x * (3.0 - 2.0 * x);
+}
+
+uvec3 ComputeLightTileCoord(vec2 tile_coord, float view_depth)
+{
+	uint tx = uint(clamp(floor(tile_coord.x), 0.0, float(LIGHT_TILES_X - 1)));
+	uint ty = uint(clamp(floor(tile_coord.y), 0.0, float(LIGHT_TILES_Y - 1)));
+	float z = max(view_depth, 1e-6);
+	float tzf = clamp(log2(z) * ZLogScale + ZLogBias, 0.0, float(LIGHT_TILES_Z - 1));
+	return uvec3(tx, ty, uint(tzf));
+}
+
+int ShadowSlotForLight(int lightIndex)
+{
+	if (abs(ShadowDLightIndices.x - float(lightIndex)) < 0.5) return 0;
+	if (abs(ShadowDLightIndices.y - float(lightIndex)) < 0.5) return 1;
+	if (abs(ShadowDLightIndices.z - float(lightIndex)) < 0.5) return 2;
+	if (abs(ShadowDLightIndices.w - float(lightIndex)) < 0.5) return 3;
+	return -1;
+}
+
+float SampleDLightShadow(int lightIndex, vec3 worldPos, vec3 lightPos, float radius)
+{
+	if (ShadowEnableDebug.x < 0.5 || ShadowEnableDebug.z < 0.5)
+		return 1.0;
+
+	int slot = ShadowSlotForLight(lightIndex);
+	if (slot < 0)
+		return 1.0;
+
+	vec3 dir = worldPos - lightPos;
+	float dist = length(dir);
+	if (dist <= 1e-5 || radius <= 1e-5)
+		return 1.0;
+
+	vec3 dirN = dir / dist;
+	float ref = dist / radius;
+	float bias = max(ShadowBiasCounts.z, 0.0);
+	// Receiver bias: scales with depth derivative to reduce acne on angled surfaces.
+	// ShadowBiasCounts.w carries the receiver-bias scale (same as world.frag).
+	float receiver_bias = max(fwidth(ref), 0.0) * max(ShadowBiasCounts.w, 0.0);
+	bias += receiver_bias;
+	float pcf = max(ShadowPCFTexel.y, 0.0) * max(ShadowPCFTexel.w, 0.0) * 2.0;
+
+	vec3 axis = (abs(dirN.z) < 0.999) ? vec3(0.0, 0.0, 1.0) : vec3(0.0, 1.0, 0.0);
+	vec3 tangent = normalize(cross(axis, dirN));
+	vec3 bitangent = normalize(cross(dirN, tangent));
+	float vis = 0.0;
+	float taps = 0.0;
+	for (int i = 0; i < 4; ++i)
+	{
+		vec2 o = vec2((i & 1) == 0 ? -1.0 : 1.0, (i < 2) ? -1.0 : 1.0) * pcf;
+		vec3 sampleDir = normalize(dirN + tangent * o.x + bitangent * o.y);
+		float closest = texture(DLightShadowTex, vec4(sampleDir, float(slot))).r;
+		vis += (ref - bias <= closest) ? 1.0 : 0.0;
+		taps += 1.0;
+	}
+	return vis / max(taps, 1.0);
+}
+
+void main()
+{
+	vec2 uv = in_uv;
+#if BINDLESS
+	sampler2D baseSampler = sampler2D(in_samplers0.xy);
+	vec4 texel = texture(baseSampler, uv);
+#else
+	vec4 texel = texture(Tex, uv);
+#endif
+
+#if ALPHATEST
+	if (texel.a < 0.666)
+		discard;
+#endif
+
+	float alpha = texel.a * in_alpha;
+	vec3 albedo = texel.rgb;
+	int debug_mode = int(ColorSpaceParams.x + 0.5);
+	if (debug_mode == 1)
+	{
+		out_fragcolor = vec4(albedo, 1.0);
+		// Keep MRT1 untouched in additive dlight pass; it stores motion/material tags.
+		out_velocity = vec4(0.0);
+		return;
+	}
+
+	vec3 surface_normal = in_normal;
+	float surface_normal_len = length(surface_normal);
+	if (surface_normal_len > 1e-8)
+	{
+		surface_normal /= surface_normal_len;
+	}
+	else
+	{
+		vec3 gn = cross(dFdx(in_pos), dFdy(in_pos));
+		float gl = length(gn);
+		surface_normal = (gl > 0.0) ? (gn / gl) : vec3(0.0, 0.0, 1.0);
+	}
+	if (!gl_FrontFacing)
+		surface_normal = -surface_normal;
+	vec3 to_eye = EyePos - in_pos;
+	float to_eye_len_sq = dot(to_eye, to_eye);
+	vec3 view_dir = (to_eye_len_sq > 1e-8) ? (to_eye * inversesqrt(to_eye_len_sq)) : vec3(0.0, 0.0, 1.0);
+	float rim_factor = 0.0;
+	if (RimLightParams0.x > 0.5 && RimLightParams1.x > 0.5)
+	{
+		float rim_ndotv = 1.0 - clamp(dot(surface_normal, view_dir), 0.0, 1.0);
+		rim_factor = pow(max(rim_ndotv, 0.0), max(RimLightParams0.z, 0.5)) * max(RimLightParams0.y, 0.0);
+	}
+	int pp_debug_mode = int(DLightParams.w + 0.5);
+	vec3 dynamic_light = vec3(0.0);
+	vec3 dynamic_light_legacy = vec3(0.0);
+	vec3 rim_dlight_accum = vec3(0.0);
+	float debug_attenuation = 0.0;
+	float debug_affected_count = 0.0;
+	uvec3 tile_coord = ComputeLightTileCoord(in_coord, in_depth);
+	uint tile_index = tile_coord.z * uint(LIGHT_TILES_X * LIGHT_TILES_Y) + tile_coord.y * uint(LIGHT_TILES_X) + tile_coord.x;
+	bool use_tile_lists = (DLightParams.z > 0.5);
+	if (NumLights > 0u)
+	{
+		const float core_boost       = 0.0;  // hook: extra brightness at light core (0=off)
+		const float core_exp         = 1.0;  // hook: exponent for core_boost shaping
+		const float knee             = 0.0;  // hook: soft-knee compression (0=off)
+		const float ndotl_mix        = 1.0;  // hook: 0=flat, 1=full Lambert
+		const float saturation_chop  = 0.0;  // hook: desaturate dynamic light (0=off)
+		uint light_begin = 0u;
+		uint light_end = NumLights;
+		if (use_tile_lists)
+		{
+			uvec2 tile_range = LightTileRanges[tile_index];
+			light_begin = tile_range.x;
+			light_end = tile_range.x + tile_range.y;
+		}
+
+		for (uint light_iter = light_begin; light_iter < light_end; light_iter++)
+		{
+			uint light_index = use_tile_lists ? LightTileIndices[light_iter] : light_iter;
+			if (light_index >= NumLights)
+				continue;
+			Light l = Lights[light_index];
+
+			float rad = l.radius;
+			vec3 to_light = l.origin - in_pos;
+			float rad_sq = rad * rad;
+			float dist_sq = dot(to_light, to_light);
+			if (dist_sq >= rad_sq)
+				continue;
+			float surface_dist = sqrt(max(dist_sq, 1e-12));
+			float minlight = l.minlight;
+			if (rad - surface_dist < minlight)
+				continue;
+
+			// Hoist light_dir once — reused for NdotL, specular, and rim
+			vec3 light_dir = (surface_dist > 0.0) ? (to_light / surface_dist) : vec3(0.0, 0.0, 1.0);
+
+			float normalized_dist = surface_dist / max(rad, 1e-4);
+			float x = clamp(1.0 - normalized_dist, 0.0, 1.0);
+			float minlight_norm = minlight / max(rad, 1e-4);
+			float attenuation = x * x;
+			float minlight_mask = clamp((x - minlight_norm) / max(1.0 - minlight_norm, 1e-4), 0.0, 1.0);
+			float intensity = attenuation * minlight_mask;
+			float core = 1.0 + core_boost * pow(max(x, 0.0), core_exp);
+			float core_intensity = intensity * core;
+			// knee==0 → shaped == core_intensity (no division overhead on most compilers)
+			float shaped = (knee > 0.0) ? (core_intensity / (core_intensity + knee)) : core_intensity;
+
+			// Half-Lambert wrap: softens terminator, avoids hard black on back faces.
+			// Keeps energy conservative: integrates to the same total as cosine lobe.
+			float ndotl_raw = dot(surface_normal, light_dir) * 0.5 + 0.5;
+			ndotl_raw = ndotl_raw * ndotl_raw; // squared wrap → tighter than linear half-Lambert
+			float ndotl = mix(1.0, ndotl_raw, ndotl_mix);
+
+			float shadow = SampleDLightShadow(int(light_index), in_pos, l.origin, rad);
+			vec3 light_contrib = shaped * ndotl * shadow * l.color;
+			dynamic_light += light_contrib;
+			dynamic_light_legacy += intensity * shadow * l.color;
+			debug_attenuation += attenuation;
+			debug_affected_count += 1.0;
+			if (rim_factor > 1e-5 && RimLightParams1.w > 0.0)
+			{
+				float rim_shadow = (RimLightParams0.w > 0.5) ? shadow : 1.0;
+				// Reuse hoisted light_dir — no redundant division
+				float backlight = mix(0.35, 1.0, max(dot(-surface_normal, light_dir), 0.0));
+				rim_dlight_accum += shaped * rim_shadow * l.color * backlight;
+			}
+		}
+
+		// saturation_chop==0 → branch never taken; left as quality hook
+		if (saturation_chop > 0.0)
+		{
+			float luma = dot(dynamic_light, vec3(0.299, 0.587, 0.114));
+			dynamic_light = mix(dynamic_light, vec3(luma), saturation_chop);
+		}
+	}
+
+	/*
+	 * Preserve albedo detail on bright hits: soft-compress the RT-light term
+	 * before final overbright scaling, instead of relying on hard clamp only.
+	 */
+	vec3 contrib_raw = SanitizeColor(dynamic_light * DLightScale);
+	vec3 contrib_legacy_raw = SanitizeColor(dynamic_light_legacy * DLightScale);
+	vec3 contrib_clamped = ApplyLumaClamp(contrib_raw, DLightLumaClamp);
+	vec3 contrib_legacy_clamped = ApplyLumaClamp(contrib_legacy_raw, DLightLumaClamp);
+	float soft_knee = max(DLightSoftKnee, 1e-4);
+	vec3 contrib = clamp(contrib_clamped / (vec3(soft_knee) + contrib_clamped), 0.0, 1.0);
+	vec3 contrib_legacy = clamp(contrib_legacy_clamped / (vec3(soft_knee) + contrib_legacy_clamped), 0.0, 1.0);
+	/* BUGFIX: keep full material response in RT-lighting. Luma-mixing the albedo
+	 * washed out texture contrast and made light look "painted on". */
+	vec3 color = albedo * contrib;
+	float fog_att = FogAttenuation(in_pos - EyePos);
+	// Rim light is part of the scene lighting — fog attenuates it too.
+	if (rim_factor > 1e-5 && RimLightParams1.w > 0.0)
+	{
+		vec3 rim_light = rim_dlight_accum * RimLightParams1.w;
+		color += albedo * rim_light * rim_factor;
+	}
+
+	if (pp_debug_mode > 0)
+	{
+		if (pp_debug_mode == 1)
+		{
+			float debug_denom = use_tile_lists ? max(float(LightTileRanges[tile_index].y), 1.0) : max(float(NumLights), 1.0);
+			float count_norm = debug_affected_count / debug_denom;
+			color = vec3(clamp(count_norm, 0.0, 1.0));
+		}
+		else if (pp_debug_mode == 2)
+		{
+			float atten_vis = debug_attenuation / max(debug_affected_count, 1.0);
+			color = vec3(clamp(atten_vis, 0.0, 1.0));
+		}
+		else if (pp_debug_mode == 3)
+		{
+			color = clamp(dynamic_light, 0.0, 1.0);
+		}
+		else if (pp_debug_mode == 4)
+		{
+			/* Debug hook: split the new shaping model against a legacy-style approximation. */
+			float split = mod(floor(gl_FragCoord.x / 16.0), 2.0);
+			color = (split < 1.0) ? (albedo * contrib) : (albedo * contrib_legacy);
+		}
+		else if (pp_debug_mode == 5)
+		{
+			color = clamp(contrib_raw, 0.0, 1.0);
+		}
+		else if (pp_debug_mode == 6)
+		{
+			color = contrib;
+		}
+	}
+
+	if (ShadowEnableDebug.w > 1.5)
+		color = vec3(clamp(length(dynamic_light), 0.0, 1.0));
+
+	color *= fog_att;
+	color = SanitizeColor(color);
+
+	out_fragcolor = vec4(color, alpha); // FIX: war "alpha * 0.0" → Fragment immer transparent
+	// Additive dlight must not modify velocity/material-mask attachment.
+	out_velocity = vec4(0.0);
+}

Index: pakfiles/shaders/world_dlight.vert
===================================================================
--- pakfiles/shaders/world_dlight.vert	
+++ pakfiles/shaders/world_dlight.vert	
@@ -0,0 +1,189 @@
+#if defined(GL_ARB_shader_draw_parameters)
+        #extension GL_ARB_shader_draw_parameters : require
+        #define DRAW_ID                 gl_DrawIDARB
+#else
+        layout(location=0) uniform int DrawID;
+        #define DRAW_ID                 DrawID
+#endif
+
+#include "frame_uniforms.glsl"
+
+#ifndef MODE
+#define MODE 0
+#endif
+
+#define LIGHT_TILES_X 32
+#define LIGHT_TILES_Y 16
+#define LIGHT_TILES_Z 32
+#define MAX_LIGHTS    64
+
+struct Light
+{
+        vec3    origin;
+        float   radius;
+        vec3    color;
+        float   minlight;
+};
+
+layout(std430, binding=0) restrict readonly buffer LightBuffer
+{
+        vec2    LightStyles[64];
+        Light   Lights[];
+};
+
+struct Call
+{
+        uint    flags;
+        uint    tcgen;
+        float   wateralpha;
+        int     spec_mode;
+        vec2    polygon_offset;
+        vec2    specular;
+        vec4    stage_color;
+#if BINDLESS
+        uvec2   txhandle;
+        uvec2   fbhandle;
+        uvec2   emhandle;
+        uvec2   nmhandle;
+        uvec2   smhandle;
+#else
+        int     baseinstance;
+        int     padding[3];
+#endif // BINDLESS
+};
+const uint
+        CF_USE_POLYGON_OFFSET = 1u,
+        CF_USE_FULLBRIGHT = 2u,
+        CF_NOLIGHTMAP = 4u,
+        CF_USE_EMISSIVE = 8u,
+        CF_ALPHA_TEST = 16u
+;
+
+const uint
+	TCGEN_BASE = 0u,
+	TCGEN_LIGHTMAP = 1u,
+	TCGEN_ENVIRONMENT = 2u;
+
+layout(std430, binding=1) restrict readonly buffer CallBuffer
+{
+        Call call_data[];
+};
+
+#if BINDLESS
+        #define GET_INSTANCE_ID(call) (gl_BaseInstanceARB + gl_InstanceID)
+#else
+        #define GET_INSTANCE_ID(call) (call.baseinstance + gl_InstanceID)
+#endif
+struct Instance
+{
+        vec4    mat[3];
+        vec4    prev_mat[3];
+        float   alpha;
+        float   pad0;
+        float   pad1;
+        float   pad2;
+};
+
+layout(std430, binding=2) restrict readonly buffer InstanceBuffer
+{
+        Instance instance_data[];
+};
+
+vec3 TransformPosition(vec3 p, vec4 mat[3])
+{
+        mat4x3 world = transpose(mat3x4(mat[0], mat[1], mat[2]));
+        return (world * vec4(p, 1.0)).xyz;
+}
+
+vec3 Transform(vec3 p, Instance instance)
+{
+        return TransformPosition(p, instance.mat);
+}
+
+vec3 TransformDirection(vec3 n, Instance instance)
+{
+        mat4x3 world = transpose(mat3x4(instance.mat[0], instance.mat[1], instance.mat[2]));
+        return (world * vec4(n, 0.0)).xyz;
+}
+
+layout(location=0) in vec3 in_pos;
+layout(location=1) in vec4 in_uv;
+layout(location=2) in float in_lmofs;
+layout(location=3) in ivec4 in_styles;
+layout(location=4) in vec3 in_normal;
+layout(location=5) in vec3 in_lightgrid;
+
+layout(location=0) flat out uint out_flags;
+layout(location=1) flat out float out_alpha;
+layout(location=2) out vec3 out_pos;
+layout(location=3) out vec2 out_uv;
+layout(location=4) out float out_depth;
+layout(location=5) noperspective out vec2 out_coord;
+layout(location=6) out vec3 out_normal;
+#if BINDLESS
+        layout(location=7) flat out uvec4 out_samplers0;
+        layout(location=8) flat out uvec2 out_samplers1;
+#endif
+
+vec2 ComputeEnvUV(vec3 world_pos, vec3 world_normal)
+{
+	vec3 view_dir = normalize(EyePos - world_pos);
+	vec3 refl = reflect(-view_dir, normalize(world_normal));
+	vec3 refl_view = mat3(View) * refl;
+	float m = 2.0 * sqrt(refl_view.x * refl_view.x + refl_view.y * refl_view.y + (refl_view.z + 1.0) * (refl_view.z + 1.0));
+	return refl_view.xy / max(m, 1e-6) + 0.5;
+}
+
+void main()
+{
+        Call call = call_data[DRAW_ID];
+        int instance_id = GET_INSTANCE_ID(call);
+        Instance instance = instance_data[instance_id];
+        vec3 world_pos = Transform(in_pos, instance);
+        vec3 world_normal = TransformDirection(in_normal, instance);
+        vec4 curr_clip = ViewProj * vec4(world_pos, 1.0);
+#if REVERSED_Z
+        const float ZBIAS = -1./1024;
+#else
+        const float ZBIAS =  1./1024;
+#endif
+        if ((call.flags & CF_USE_POLYGON_OFFSET) != 0u)
+        {
+                float zoffset = (call.polygon_offset.x + call.polygon_offset.y) * ZBIAS;
+
+                curr_clip.z += zoffset;
+        }
+        gl_Position = curr_clip;
+        out_pos = world_pos;
+        out_normal = normalize(world_normal);
+	vec2 uv = in_uv.xy;
+	if (call.tcgen == TCGEN_LIGHTMAP)
+		uv = in_uv.zw;
+	else if (call.tcgen == TCGEN_ENVIRONMENT)
+		uv = ComputeEnvUV(world_pos, world_normal);
+        out_uv = uv;
+        out_depth = gl_Position.w;
+        // BP #7: out_coord für Licht-Tiles wird hier in NDC-Raum berechnet
+        // (nach Perspektivdivision). Das ist korrekt für Screen-Space-Tiles,
+        // aber die Tiles sollten konsistent zu den Fragment-Tiles in world_dlight.frag
+        // sein. Wenn der Fragment-Shader in_coord nicht für Tile-Lookups nutzt
+        // (aktuell nur NumLights-Loop), ist das harmlos aber dokumentationswürdig.
+        out_coord = (gl_Position.xy / gl_Position.w * 0.5 + 0.5) * vec2(LIGHT_TILES_X, LIGHT_TILES_Y);
+        out_flags = call.flags;
+#if MODE == 2
+        out_alpha = instance.alpha < 0.0 ? call.wateralpha : instance.alpha;
+#else
+        out_alpha = instance.alpha < 0.0 ? 1.0 : instance.alpha;
+#endif
+#if BINDLESS
+        out_samplers0.xy = call.txhandle;
+        if ((call.flags & CF_USE_FULLBRIGHT) != 0u)
+                out_samplers0.zw = call.fbhandle;
+        else
+                out_samplers0.zw = uvec2(0u);
+        if ((call.flags & CF_USE_EMISSIVE) != 0u)
+                out_samplers1.xy = call.emhandle;
+        else
+                out_samplers1.xy = uvec2(0u);
+#endif
+}

Index: pakfiles/shaders/world_shadow.frag
===================================================================
--- pakfiles/shaders/world_shadow.frag	
+++ pakfiles/shaders/world_shadow.frag	
@@ -0,0 +1,23 @@
+// BUG FIX: location=4 collided with ShadowViewProj (mat4 uses locations 4-7) in the vertex shader.
+// ShadowLightPosFar -> 8 (first free slot after mat4), ShadowMode -> 9.
+layout(location=8) uniform vec4 ShadowLightPosFar; // xyz: light pos, w: far plane
+layout(location=9) uniform int ShadowMode;          // 0=sun, 1=dlight cube
+
+layout(location=0) in vec3 in_world_pos;
+
+void main()
+{
+	if (ShadowMode != 0)
+	{
+		// Cubemap dlight shadow: linear distance normalized to [0,1].
+		float farPlane = max(ShadowLightPosFar.w, 1e-5);
+		float dist = length(in_world_pos - ShadowLightPosFar.xyz);
+		gl_FragDepth = clamp(dist / farPlane, 0.0, 1.0);
+	}
+	else
+	{
+		// Sun shadow: take rasterizer depth as-is. CPU shadow pass renders in
+		// classic non-reversed depth space for consistent receiver comparisons.
+		gl_FragDepth = gl_FragCoord.z;
+	}
+}

Index: pakfiles/shaders/world_shadow.vert
===================================================================
--- pakfiles/shaders/world_shadow.vert	
+++ pakfiles/shaders/world_shadow.vert	
@@ -0,0 +1,83 @@
+#if BINDLESS
+#extension GL_ARB_shader_draw_parameters : require
+#define DRAW_ID gl_DrawIDARB
+#else
+layout(location=0) uniform int DrawID;
+#define DRAW_ID DrawID
+#endif
+
+// BUG FIX: location=0 kollidierte mit dem vertex attrib in_pos (location=0).
+// ShadowViewProj belegt locations 0-3 (mat4 = 4 konsekutive slots) — in_pos war
+// dadurch undefiniert. Verschoben auf location=4 (erste freie Slot nach mat4).
+layout(location=4) uniform mat4 ShadowViewProj;
+
+struct Call
+{
+	uint flags;
+	uint tcgen;
+	float wateralpha;
+	int spec_mode;
+	vec2 polygon_offset;
+	vec2 specular;
+	vec4 stage_color;
+#if BINDLESS
+	uvec2 txhandle;
+	uvec2 fbhandle;
+	uvec2 emhandle;
+	uvec2 nmhandle;
+	uvec2 smhandle;
+#else
+	int baseinstance;
+	int padding[3];
+#endif
+};
+
+const uint CF_USE_POLYGON_OFFSET = 1u;
+
+layout(std430, binding=1) restrict readonly buffer CallBuffer
+{
+	Call call_data[];
+};
+
+#if BINDLESS
+#define GET_INSTANCE_ID(call) (gl_BaseInstanceARB + gl_InstanceID)
+#else
+#define GET_INSTANCE_ID(call) (call.baseinstance + gl_InstanceID)
+#endif
+
+struct Instance
+{
+	vec4 mat[3];
+	vec4 prev_mat[3];
+	float alpha;
+	float pad0;
+	float pad1;
+	float pad2;
+};
+
+layout(std430, binding=2) restrict readonly buffer InstanceBuffer
+{
+	Instance instance_data[];
+};
+
+layout(location=0) in vec3 in_pos;
+layout(location=0) out vec3 out_world_pos;  // location=0 als Output ist korrekt (anderes Interface)
+
+void main()
+{
+	Call call = call_data[DRAW_ID];
+	int instance_id = GET_INSTANCE_ID(call);
+	Instance instance = instance_data[instance_id];
+	mat4x3 world = transpose(mat3x4(instance.mat[0], instance.mat[1], instance.mat[2]));
+	vec3 world_pos = (world * vec4(in_pos, 1.0)).xyz;
+	vec4 clip = ShadowViewProj * vec4(world_pos, 1.0);
+	/* Shadow-map depth is rendered in classic non-reversed space. */
+	const float ZBIAS = 1.0 / 1024.0;
+	if ((call.flags & CF_USE_POLYGON_OFFSET) != 0u)
+	{
+		float zoffset = (call.polygon_offset.x + call.polygon_offset.y) * ZBIAS;
+		clip.z += zoffset;
+	}
+	gl_Position = clip;
+	out_world_pos = world_pos;
+}
